window.AtlasChapters=(window.AtlasChapters||[]).concat([{"id":21,"title":"21단계 — 과거진행형 was / were + -ing","html":"\u003ch1 id=\"lesson-title\" data-id=\"21\">21단계 — 과거진행형 \u003ccode>was / were + -ing\u003c/code>\u003c/h1>\n\u003cp>과거진행형은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>과거의 특정 시점에 진행 중이던 행동\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>을 말할 때 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + was/were + 동사-ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>was working\u003c/strong> at 9 p.m.\u003cbr>나는 밤 9시에 일하고 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They \u003cstrong>were eating\u003c/strong> dinner.\u003cbr>그들은 저녁을 먹고 있었다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>was / were\u003c/code> 구분\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>주어\u003c/th>\n\u003cth>과거진행형\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>I\u003c/td>\n\u003ctd>was working\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>he\u003c/td>\n\u003ctd>was working\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>she\u003c/td>\n\u003ctd>was working\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>it\u003c/td>\n\u003ctd>was working\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>you\u003c/td>\n\u003ctd>were working\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>we\u003c/td>\n\u003ctd>were working\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>they\u003c/td>\n\u003ctd>were working\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>현재진행형의:\u003c/p>\n\u003cblockquote>\n\u003cp>am / is / are\u003c/p>\n\u003c/blockquote>\n\u003cp>가 과거에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>was / were\u003c/p>\n\u003c/blockquote>\n\u003cp>로 바뀐다고 보면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 과거시제와 차이\u003c/h2>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">과거시제\u003c/h3>\n\u003cblockquote>\n\u003cp>I worked yesterday.\u003cbr>나는 어제 일했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 과거의 \u003cstrong>완료된 사실\u003c/strong>\u003c/p>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">과거진행형\u003c/h3>\n\u003cblockquote>\n\u003cp>I was working at 3 p.m. yesterday.\u003cbr>나는 어제 오후 3시에 일하고 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 그 시점에 \u003cstrong>진행 중\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 특정 시점과 함께 자주 사용\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>at 8 p.m.\u003cbr>at that time\u003cbr>when you called me\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">예문\u003c/h3>\n\u003cblockquote>\n\u003cp>I was sleeping at 11 p.m.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She was driving at that time.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. \u003ccode>when\u003c/code>과 함께 자주 나온다\u003c/h2>\n\u003cp>과거에 어떤 행동이 진행 중일 때 다른 일이 일어나는 구조다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>was sleeping\u003c/strong> when you called me.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>네가 전화했을 때 나는 자고 있었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>진행 중이던 일 + 갑자기 일어난 일\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">진행 중\u003c/h3>\n\u003cblockquote>\n\u003cp>was sleeping\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">발생한 일\u003c/h3>\n\u003cblockquote>\n\u003cp>called\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">6. 비교\u003c/h2>\n\u003cblockquote>\n\u003cp>I cooked dinner.\u003c/p>\n\u003c/blockquote>\n\u003cp>저녁을 요리했다.\u003c/p>\n\u003cblockquote>\n\u003cp>I was cooking dinner.\u003c/p>\n\u003c/blockquote>\n\u003cp>저녁을 요리하고 있었다.\u003c/p>\n\u003cp>둘의 차이는 \u003cstrong>진행 중이라는 관점\u003c/strong>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">7. 부정문\u003c/h2>\n\u003cp>\u003ccode>was/were\u003c/code> 뒤에 \u003ccode>not\u003c/code>.\u003c/p>\n\u003cblockquote>\n\u003cp>I was not working.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They were not sleeping.\u003c/p>\n\u003c/blockquote>\n\u003cp>축약:\u003c/p>\n\u003cblockquote>\n\u003cp>wasn&#39;t\u003cbr>weren&#39;t\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>She wasn&#39;t driving.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We weren&#39;t waiting.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">8. 의문문\u003c/h2>\n\u003cp>\u003ccode>was/were\u003c/code>를 앞으로 보낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>You were working.\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Were you working?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She was sleeping.\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Was she sleeping?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">9. \u003ccode>did\u003c/code>를 쓰지 않는다\u003c/h2>\n\u003cp>과거진행형에는 이미 \u003ccode>was/were\u003c/code>가 있다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Did you working?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>✅ Were you working?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">핵심\u003c/h2>\n\u003cp>과거진행형:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>was/were + 동사-ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>의미:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>과거 특정 시점에 진행 중이던 행동\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>비교:\u003c/p>\n\u003cblockquote>\n\u003cp>I worked.\u003cbr>과거 사실\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I was working.\u003cbr>과거에 진행 중\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>I \u003cstrong>was sleeping / slept\u003c/strong> at 2 a.m.\u003cbr>→ 새벽 2시에 자고 있던 중\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She \u003cstrong>was driving / drove\u003c/strong> when I called her.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>They \u003cstrong>were eating / ate\u003c/strong> at 7 p.m.\u003cbr>→ 오후 7시에 식사하고 있던 중\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003cstrong>Did you working / Were you working\u003c/strong> then?\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>He \u003cstrong>wasn&#39;t sleep / wasn&#39;t sleeping\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음 단계는 \u003cstrong>22단계 — 조동사 \u003ccode>can / should / must\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 구조","depth":2},{"id":"reading-2","label":"2. was / were 구분","depth":2},{"id":"reading-3","label":"3. 과거시제와 차이","depth":2},{"id":"reading-4","label":"과거시제","depth":3},{"id":"reading-5","label":"과거진행형","depth":3},{"id":"reading-6","label":"4. 특정 시점과 함께 자주 사용","depth":2},{"id":"reading-7","label":"예문","depth":3},{"id":"reading-8","label":"5. when과 함께 자주 나온다","depth":2},{"id":"reading-9","label":"진행 중","depth":3},{"id":"reading-10","label":"발생한 일","depth":3},{"id":"reading-11","label":"6. 비교","depth":2},{"id":"reading-12","label":"7. 부정문","depth":2},{"id":"reading-13","label":"8. 의문문","depth":2},{"id":"reading-14","label":"9. did를 쓰지 않는다","depth":2},{"id":"reading-15","label":"핵심","depth":2},{"id":"reading-16","label":"연습","depth":2}],"origin":"conversation","characters":2051,"aliases":{"structure":"reading-1","examples":"reading-7","contrast":"reading-2","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-6","topic-5":"reading-8","topic-6":"reading-11","topic-7":"reading-12","topic-8":"reading-13","topic-9":"reading-14","topic-10":"reading-15","topic-11":"reading-16","topic-12":"concept"}},{"id":22,"title":"22단계 — 조동사의 기본 + can","html":"\u003ch1 id=\"lesson-title\" data-id=\"22\">22단계 — 조동사의 기본 + \u003ccode>can\u003c/code>\u003c/h1>\n\u003cp>조동사는 일반동사 앞에 붙어서 \u003cstrong>가능, 능력, 의무, 조언, 추측\u003c/strong> 같은 의미를 더한다.\u003c/p>\n\u003cp>이번 단계에서는 조동사의 구조와 가장 기본적인 \u003ccode>can\u003c/code>만 배운다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + 조동사 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>can swim\u003c/strong>.\u003cbr>나는 수영할 수 있다.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>I = 주어\u003c/li>\n\u003cli>can = 조동사\u003c/li>\n\u003cli>swim = 동사원형\u003c/li>\n\u003c/ul>\n\u003cp>여기서 중요한 규칙:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>조동사 뒤에는 항상 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>he / she / it\u003c/code>이어도 동사에 \u003ccode>-s\u003c/code>를 붙이지 않는다\u003c/h2>\n\u003cp>현재시제에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>She work\u003cstrong>s\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 \u003ccode>can\u003c/code>이 있으면:\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>can work\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ She can works.\u003cbr>✅ She can work.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>can\u003c/code>이 문법 기능을 담당하므로 뒤의 동사는 원형으로 둔다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>can\u003c/code>의 가장 기본적인 의미 — 능력\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>~할 수 있다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">예\u003c/h3>\n\u003cblockquote>\n\u003cp>I can swim.\u003cbr>나는 수영할 수 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She can speak English.\u003cbr>그녀는 영어를 할 수 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Narin can read.\u003cbr>나린이는 읽을 수 있다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">4. 가능성·상황상 가능함\u003c/h2>\n\u003cp>\u003ccode>can\u003c/code>은 단순한 개인 능력뿐 아니라:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~할 수 있다 / ~하는 것이 가능하다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻도 가진다.\u003c/p>\n\u003cblockquote>\n\u003cp>We can go now.\u003cbr>우리 지금 갈 수 있어.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You can use this computer.\u003cbr>이 컴퓨터 사용해도 돼.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">5. 허락\u003c/h2>\n\u003cp>회화에서는 \u003ccode>can\u003c/code>으로 허락을 묻거나 허락할 수도 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>Can I sit here?\u003cbr>여기 앉아도 돼요?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You can go home now.\u003cbr>이제 집에 가도 돼.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 \u003ccode>can\u003c/code>에는 크게:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>능력 / 가능 / 허락\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">6. 부정문\u003c/h2>\n\u003cp>\u003ccode>can\u003c/code> 뒤에 \u003ccode>not\u003c/code>.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>cannot\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>또는 축약형:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>can&#39;t\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I can&#39;t swim.\u003cbr>나는 수영을 못한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She can&#39;t come today.\u003cbr>그녀는 오늘 올 수 없다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">문장 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + can&#39;t + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ She can&#39;t comes.\u003cbr>✅ She can&#39;t come.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. 의문문\u003c/h2>\n\u003cp>\u003ccode>can\u003c/code>을 주어 앞으로 보낸다.\u003c/p>\n\u003cp>평서문:\u003c/p>\n\u003cblockquote>\n\u003cp>You can swim.\u003c/p>\n\u003c/blockquote>\n\u003cp>질문:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Can you swim?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>평서문:\u003c/p>\n\u003cblockquote>\n\u003cp>She can come.\u003c/p>\n\u003c/blockquote>\n\u003cp>질문:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Can she come?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Can + 주어 + 동사원형?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. \u003ccode>do / does\u003c/code>를 쓰지 않는다\u003c/h2>\n\u003cp>\u003ccode>can\u003c/code> 자체가 조동사이기 때문에 질문이나 부정에서 \u003ccode>do\u003c/code>가 필요 없다.\u003c/p>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">질문\u003c/h3>\n\u003cblockquote>\n\u003cp>❌ Do you can swim?\u003cbr>✅ Can you swim?\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">부정\u003c/h3>\n\u003cblockquote>\n\u003cp>❌ I don&#39;t can swim.\u003cbr>✅ I can&#39;t swim.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">9. 일반동사와 비교\u003c/h2>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">일반동사 현재형\u003c/h3>\n\u003cblockquote>\n\u003cp>She works.\u003c/p>\n\u003c/blockquote>\n\u003cp>부정:\u003c/p>\n\u003cblockquote>\n\u003cp>She doesn&#39;t work.\u003c/p>\n\u003c/blockquote>\n\u003cp>질문:\u003c/p>\n\u003cblockquote>\n\u003cp>Does she work?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">조동사 \u003ccode>can\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>She can work.\u003c/p>\n\u003c/blockquote>\n\u003cp>부정:\u003c/p>\n\u003cblockquote>\n\u003cp>She can&#39;t work.\u003c/p>\n\u003c/blockquote>\n\u003cp>질문:\u003c/p>\n\u003cblockquote>\n\u003cp>Can she work?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>can\u003c/code>이 있으면 \u003ccode>do / does\u003c/code>가 사라지는 것이 핵심이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">10. 조동사의 공통 구조\u003c/h2>\n\u003cp>앞으로 배울:\u003c/p>\n\u003cblockquote>\n\u003cp>can\u003cbr>should\u003cbr>must\u003cbr>will\u003cbr>may\u003cbr>might\u003c/p>\n\u003c/blockquote>\n\u003cp>같은 조동사들은 기본적으로 모두:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>조동사 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>구조를 사용한다.\u003c/p>\n\u003cp>이미 배운 \u003ccode>will\u003c/code>도 사실 조동사다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>will go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>go\u003c/code>가 원형인 이유도 같은 규칙이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">핵심\u003c/h2>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">긍정\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>can swim\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">부정\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>can&#39;t swim\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">질문\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>Can\u003c/strong> you \u003cstrong>swim\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고 가장 중요한 규칙:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>조동사 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>can go\u003cbr>can eat\u003cbr>can work\u003cbr>can play\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>She can \u003cstrong>swim / swims\u003c/strong>.\u003c/li>\n\u003cli>He can \u003cstrong>drive / drives\u003c/strong>.\u003c/li>\n\u003cli>I \u003cstrong>don&#39;t can / can&#39;t\u003c/strong> go today.\u003c/li>\n\u003cli>\u003cstrong>Can you speak / Do you can speak\u003c/strong> English?\u003c/li>\n\u003cli>Narin can \u003cstrong>reads / read\u003c/strong> this book.\u003c/li>\n\u003cli>They \u003cstrong>can come / can comes\u003c/strong> tomorrow.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>23단계 — \u003ccode>should\u003c/code> : 조언과 권고\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 구조","depth":2},{"id":"reading-2","label":"2. he / she / it이어도 동사에 -s를 붙이지 않는다","depth":2},{"id":"reading-3","label":"3. can의 가장 기본적인 의미 — 능력","depth":2},{"id":"reading-4","label":"예","depth":3},{"id":"reading-5","label":"4. 가능성·상황상 가능함","depth":2},{"id":"reading-6","label":"5. 허락","depth":2},{"id":"reading-7","label":"6. 부정문","depth":2},{"id":"reading-8","label":"문장 구조","depth":2},{"id":"reading-9","label":"7. 의문문","depth":2},{"id":"reading-10","label":"8. do / does를 쓰지 않는다","depth":2},{"id":"reading-11","label":"질문","depth":3},{"id":"reading-12","label":"부정","depth":3},{"id":"reading-13","label":"9. 일반동사와 비교","depth":2},{"id":"reading-14","label":"일반동사 현재형","depth":3},{"id":"reading-15","label":"조동사 can","depth":3},{"id":"reading-16","label":"10. 조동사의 공통 구조","depth":2},{"id":"reading-17","label":"핵심","depth":2},{"id":"reading-18","label":"긍정","depth":3},{"id":"reading-19","label":"부정","depth":3},{"id":"reading-20","label":"질문","depth":3},{"id":"reading-21","label":"연습","depth":2}],"origin":"conversation","characters":2447,"aliases":{"structure":"reading-1","examples":"reading-4","contrast":"reading-13","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-5","topic-5":"reading-6","topic-6":"reading-7","topic-7":"reading-8","topic-8":"reading-9","topic-9":"reading-10","topic-10":"reading-13","topic-11":"reading-16","topic-12":"reading-17"}},{"id":23,"title":"23단계 — should","html":"\u003ch1 id=\"lesson-title\" data-id=\"23\">23단계 — \u003ccode>should\u003c/code>\u003c/h1>\n\u003cp>\u003ccode>should\u003c/code>는 가장 기본적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~하는 게 좋다 / ~해야 한다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 \u003cstrong>조언·권고\u003c/strong>를 나타낸다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + should + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>You \u003cstrong>should rest\u003c/strong>.\u003cbr>너는 쉬는 게 좋다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>should study\u003c/strong> more.\u003cbr>그녀는 더 공부하는 게 좋다.\u003c/p>\n\u003c/blockquote>\n\u003cp>다시 중요한 규칙:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>should 뒤에는 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 3인칭 단수라도 \u003ccode>-s\u003c/code> 없음\u003c/h2>\n\u003cblockquote>\n\u003cp>She should go.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ She should goes.\u003cbr>✅ She should go.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>can\u003c/code>, \u003ccode>will\u003c/code>과 똑같다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>should\u003c/code>의 핵심 의미\u003c/h2>\n\u003cp>보통 강한 명령이 아니라:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>내 생각에는 이게 좋다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 느낌이다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>You should see a doctor.\u003cbr>병원에 가보는 게 좋겠어.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You should get some sleep.\u003cbr>좀 자는 게 좋겠어.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>should\u003c/code>와 \u003ccode>must\u003c/code>의 차이\u003c/h2>\n\u003cp>이 차이가 중요하다.\u003c/p>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">should\u003c/h3>\n\u003cblockquote>\n\u003cp>You should wear a seat belt.\u003c/p>\n\u003c/blockquote>\n\u003cp>안전벨트를 매는 게 좋다.\u003c/p>\n\u003cp>→ \u003cstrong>권고\u003c/strong>\u003c/p>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">must\u003c/h3>\n\u003cblockquote>\n\u003cp>You must wear a seat belt.\u003c/p>\n\u003c/blockquote>\n\u003cp>안전벨트를 반드시 매야 한다.\u003c/p>\n\u003cp>→ \u003cstrong>강한 의무\u003c/strong>\u003c/p>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>should = 하는 게 좋다\u003cbr>must = 반드시 해야 한다\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. 부정문\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>should not\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>축약:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>shouldn&#39;t\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>You shouldn&#39;t eat too much.\u003c/p>\n\u003c/blockquote>\n\u003cp>너는 너무 많이 먹지 않는 게 좋다.\u003c/p>\n\u003cblockquote>\n\u003cp>She shouldn&#39;t drive now.\u003c/p>\n\u003c/blockquote>\n\u003cp>그녀는 지금 운전하지 않는 게 좋다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. 의문문\u003c/h2>\n\u003cp>\u003ccode>should\u003c/code>를 주어 앞으로 보낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Should I go?\u003c/strong>\u003cbr>내가 가는 게 좋을까?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Should we wait?\u003c/strong>\u003cbr>우리 기다리는 게 좋을까?\u003c/p>\n\u003c/blockquote>\n\u003cp>이 형태는 실제 회화에서도 매우 자주 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. \u003ccode>do / does\u003c/code>는 쓰지 않는다\u003c/h2>\n\u003cp>\u003ccode>should\u003c/code>가 이미 조동사다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Do I should go?\u003cbr>✅ Should I go?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ She doesn&#39;t should go.\u003cbr>✅ She shouldn&#39;t go.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. \u003ccode>should\u003c/code>가 자주 쓰이는 구조\u003c/h2>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">You should + 동사\u003c/h3>\n\u003cblockquote>\n\u003cp>You should try it.\u003cbr>그거 해보는 게 좋아.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You should ask her.\u003cbr>그녀에게 물어보는 게 좋아.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">I should + 동사\u003c/h3>\n\u003cp>자기 자신에게도 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>I should go home.\u003c/p>\n\u003c/blockquote>\n\u003cp>나 집에 가야겠다.\u003c/p>\n\u003cp>이때는 아주 강한 의무라기보다:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>이제 집에 가는 게 좋겠다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 느낌이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">9. \u003ccode>should probably\u003c/code>\u003c/h2>\n\u003cp>회화에서 많이 쓰는 조합이다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>should probably + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>아마 ~하는 게 좋겠다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>We should probably leave now.\u003c/p>\n\u003c/blockquote>\n\u003cp>우리 이제 슬슬 가는 게 좋겠다.\u003c/p>\n\u003cp>\u003ccode>probably\u003c/code>가 들어가면서 표현이 조금 더 부드러워진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">10. 지금까지 조동사 비교\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>조동사\u003c/th>\n\u003cth>기본 의미\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>can\u003c/td>\n\u003ctd>~할 수 있다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>will\u003c/td>\n\u003ctd>~할 것이다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>should\u003c/td>\n\u003ctd>~하는 게 좋다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>must\u003c/td>\n\u003ctd>반드시 ~해야 한다\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>공통점:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>조동사 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">핵심\u003c/h2>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">긍정\u003c/h3>\n\u003cblockquote>\n\u003cp>You \u003cstrong>should rest\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">부정\u003c/h3>\n\u003cblockquote>\n\u003cp>You \u003cstrong>shouldn&#39;t work\u003c/strong> too much.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">질문\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>Should I call\u003c/strong> her?\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ should goes\u003cbr>✅ should go\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>You should \u003cstrong>rest / rests\u003c/strong>.\u003c/li>\n\u003cli>She should \u003cstrong>go / goes\u003c/strong> home.\u003c/li>\n\u003cli>You \u003cstrong>shouldn&#39;t eat / don&#39;t should eat\u003c/strong> too much.\u003c/li>\n\u003cli>\u003cstrong>Should I call / Do I should call\u003c/strong> him?\u003c/li>\n\u003cli>We should probably \u003cstrong>leave / leaves\u003c/strong> now.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>24단계 — \u003ccode>must\u003c/code>와 \u003ccode>have to\u003c/code>의 차이\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 구조","depth":2},{"id":"reading-2","label":"2. 3인칭 단수라도 -s 없음","depth":2},{"id":"reading-3","label":"3. should의 핵심 의미","depth":2},{"id":"reading-4","label":"4. should와 must의 차이","depth":2},{"id":"reading-5","label":"should","depth":3},{"id":"reading-6","label":"must","depth":3},{"id":"reading-7","label":"5. 부정문","depth":2},{"id":"reading-8","label":"6. 의문문","depth":2},{"id":"reading-9","label":"7. do / does는 쓰지 않는다","depth":2},{"id":"reading-10","label":"8. should가 자주 쓰이는 구조","depth":2},{"id":"reading-11","label":"You should + 동사","depth":3},{"id":"reading-12","label":"I should + 동사","depth":3},{"id":"reading-13","label":"9. should probably","depth":2},{"id":"reading-14","label":"10. 지금까지 조동사 비교","depth":2},{"id":"reading-15","label":"핵심","depth":2},{"id":"reading-16","label":"긍정","depth":3},{"id":"reading-17","label":"부정","depth":3},{"id":"reading-18","label":"질문","depth":3},{"id":"reading-19","label":"연습","depth":2}],"origin":"conversation","characters":2263,"aliases":{"structure":"reading-1","examples":"concept","contrast":"reading-4","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-13","topic-10":"reading-14","topic-11":"reading-15","topic-12":"reading-19"}},{"id":24,"title":"24단계 — must와 have to","html":"\u003ch1 id=\"lesson-title\" data-id=\"24\">24단계 — \u003ccode>must\u003c/code>와 \u003ccode>have to\u003c/code>\u003c/h1>\n\u003cp>둘 다 기본적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~해야 한다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이다.\u003c/p>\n\u003cp>하지만 느낌이 조금 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>must\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>must\u003c/code>는 \u003cstrong>강한 의무\u003c/strong>를 나타낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>You \u003cstrong>must wear\u003c/strong> a seat belt.\u003cbr>너는 반드시 안전벨트를 매야 한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I \u003cstrong>must finish\u003c/strong> this today.\u003cbr>나는 이걸 오늘 반드시 끝내야 한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + must + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ He must goes.\u003cbr>✅ He must go.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>have to\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>have to\u003c/code>도:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~해야 한다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>have to work\u003c/strong> tomorrow.\u003cbr>나는 내일 일해야 한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>has to leave\u003c/strong> early.\u003cbr>그녀는 일찍 떠나야 한다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>have\u003c/code>와 \u003ccode>has\u003c/code>\u003c/h2>\n\u003cp>주어에 따라 바뀐다.\u003c/p>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">I / You / We / They\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>have to\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">He / She / It\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>has to\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I have to go.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She has to go.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. \u003ccode>must\u003c/code>와 \u003ccode>have to\u003c/code>의 기본 차이\u003c/h2>\n\u003cp>초급에서는 이렇게 잡으면 된다.\u003c/p>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">must\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>말하는 사람이 강하게 필요하다고 판단\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">have to\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>상황이나 규칙 때문에 해야 함\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">예\u003c/h2>\n\u003cp>내가 스스로 생각한다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>must exercise\u003c/strong> more.\u003cbr>운동을 더 해야겠어.\u003c/p>\n\u003c/blockquote>\n\u003cp>내 판단이나 강한 의지.\u003c/p>\n\u003chr>\n\u003cp>회사 규칙 때문에:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>have to wear\u003c/strong> a helmet at work.\u003cbr>나는 직장에서 헬멧을 써야 한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>외부 규칙이나 상황.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">하지만 실제 회화에서는\u003c/h2>\n\u003cp>둘이 상당히 겹친다.\u003c/p>\n\u003cp>특히 일상에서는 \u003ccode>must\u003c/code>보다 \u003cstrong>have to\u003c/strong>가 훨씬 자주 쓰이는 경우가 많다.\u003c/p>\n\u003cblockquote>\n\u003cp>I have to go now.\u003c/p>\n\u003c/blockquote>\n\u003cp>자연스럽게:\u003c/p>\n\u003cblockquote>\n\u003cp>나 이제 가야 해.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>I must go now.\u003c/code>도 맞지만 좀 더 강하거나 격식 있는 느낌이 날 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">5. 부정문에서 뜻이 크게 달라진다\u003c/h2>\n\u003cp>여기가 \u003cstrong>가장 중요하다.\u003c/strong>\u003c/p>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">\u003ccode>must not\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>하면 안 된다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>축약:\u003c/p>\n\u003cblockquote>\n\u003cp>mustn&#39;t\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>You \u003cstrong>mustn&#39;t touch\u003c/strong> this.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이걸 만지면 안 돼.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>금지\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">\u003ccode>don&#39;t have to\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>할 필요가 없다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>You \u003cstrong>don&#39;t have to come\u003c/strong> tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너는 내일 올 필요 없어.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>와도 안 된다 ❌\u003cbr>안 와도 된다 ✅\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">6. 비교\u003c/h2>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">You mustn&#39;t go.\u003c/h3>\n\u003cblockquote>\n\u003cp>너는 가면 안 된다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">You don&#39;t have to go.\u003c/h3>\n\u003cblockquote>\n\u003cp>너는 갈 필요가 없다.\u003c/p>\n\u003c/blockquote>\n\u003cp>완전히 다른 뜻이다.\u003c/p>\n\u003cp>이 차이는 반드시 기억해야 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">7. \u003ccode>have to\u003c/code>의 부정문\u003c/h2>\n\u003cp>일반동사 \u003ccode>have\u003c/code>를 사용하기 때문에 \u003ccode>do/does\u003c/code>를 쓴다.\u003c/p>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">I / You / We / They\u003c/h3>\n\u003cblockquote>\n\u003cp>don&#39;t have to\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">He / She / It\u003c/h3>\n\u003cblockquote>\n\u003cp>doesn&#39;t have to\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I don&#39;t have to work today.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She doesn&#39;t have to work today.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ She doesn&#39;t has to work.\u003cbr>✅ She doesn&#39;t have to work.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>doesn&#39;t\u003c/code> 뒤이므로 \u003ccode>has → have\u003c/code>로 돌아간다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">8. 의문문\u003c/h2>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">must\u003c/h2>\n\u003cp>조동사이므로 바로 앞으로 간다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Must I go?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>문법적으로 맞다.\u003c/p>\n\u003cp>하지만 일상 회화에서는 다소 딱딱하게 들릴 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">have to\u003c/h2>\n\u003cp>\u003ccode>do / does\u003c/code>를 사용한다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Do I have to go?\u003c/strong>\u003cbr>나 꼭 가야 해?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Does she have to work?\u003c/strong>\u003cbr>그녀는 일해야 해?\u003c/p>\n\u003c/blockquote>\n\u003cp>회화에서는 이 형태가 아주 자주 쓰인다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">9. 과거에서는 \u003ccode>had to\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>must\u003c/code>의 과거 의무를 말할 때 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>had to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>을 쓴다.\u003c/p>\n\u003cp>현재:\u003c/p>\n\u003cblockquote>\n\u003cp>I have to work.\u003c/p>\n\u003c/blockquote>\n\u003cp>과거:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>had to work\u003c/strong> yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 어제 일해야 했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>주어와 관계없이:\u003c/p>\n\u003cblockquote>\n\u003cp>I had to\u003cbr>She had to\u003cbr>They had to\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-24\" data-reading-anchor=\"reading-24\">10. 미래에서도 \u003ccode>have to\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>I \u003cstrong>will have to work\u003c/strong> tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 내일 일해야 할 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>must\u003c/code>는 시제 변화가 제한적이기 때문에\u003cbr>과거·미래에서는 \u003ccode>have to\u003c/code> 계열이 매우 중요하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-25\" data-reading-anchor=\"reading-25\">핵심 비교\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>표현\u003c/th>\n\u003cth>의미\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>should\u003c/td>\n\u003ctd>~하는 게 좋다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>must\u003c/td>\n\u003ctd>반드시 ~해야 한다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>have to\u003c/td>\n\u003ctd>~해야 한다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>mustn&#39;t\u003c/td>\n\u003ctd>하면 안 된다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>don&#39;t have to\u003c/td>\n\u003ctd>할 필요 없다\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>특히:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>mustn&#39;t ≠ don&#39;t have to\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-26\" data-reading-anchor=\"reading-26\">문장 구조\u003c/h2>\n\u003ch3 id=\"reading-27\" data-reading-anchor=\"reading-27\">must\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + must + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I must go.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-28\" data-reading-anchor=\"reading-28\">have to\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>I/You/We/They + have to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We have to go.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>He/She/It + has to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She has to go.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-29\" data-reading-anchor=\"reading-29\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>She \u003cstrong>must go / must goes\u003c/strong> now.\u003c/li>\n\u003cli>He \u003cstrong>have to / has to\u003c/strong> work tomorrow.\u003c/li>\n\u003cli>You \u003cstrong>mustn&#39;t / don&#39;t have to\u003c/strong> smoke here.\u003cbr>→ 여기서 담배를 피우면 안 된다.\u003c/li>\n\u003cli>You \u003cstrong>mustn&#39;t / don&#39;t have to\u003c/strong> come tomorrow.\u003cbr>→ 내일 올 필요 없다.\u003c/li>\n\u003cli>She \u003cstrong>doesn&#39;t have to / doesn&#39;t has to\u003c/strong> work today.\u003c/li>\n\u003cli>\u003cstrong>Do you have to / Does you have to\u003c/strong> work tomorrow? → “내일 일해야 해?”는 어떤 형태가 맞는지 생각해봐.\u003c/li>\n\u003c/ol>\n\u003cp>다음 단계는 \u003cstrong>25단계 — \u003ccode>may / might\u003c/code>와 가능성 표현\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. must","depth":2},{"id":"reading-2","label":"2. have to","depth":2},{"id":"reading-3","label":"3. have와 has","depth":2},{"id":"reading-4","label":"I / You / We / They","depth":3},{"id":"reading-5","label":"He / She / It","depth":3},{"id":"reading-6","label":"4. must와 have to의 기본 차이","depth":2},{"id":"reading-7","label":"must","depth":3},{"id":"reading-8","label":"have to","depth":3},{"id":"reading-9","label":"예","depth":2},{"id":"reading-10","label":"하지만 실제 회화에서는","depth":2},{"id":"reading-11","label":"5. 부정문에서 뜻이 크게 달라진다","depth":2},{"id":"reading-12","label":"must not","depth":2},{"id":"reading-13","label":"don't have to","depth":2},{"id":"reading-14","label":"6. 비교","depth":2},{"id":"reading-15","label":"You mustn't go.","depth":3},{"id":"reading-16","label":"You don't have to go.","depth":3},{"id":"reading-17","label":"7. have to의 부정문","depth":2},{"id":"reading-18","label":"I / You / We / They","depth":3},{"id":"reading-19","label":"He / She / It","depth":3},{"id":"reading-20","label":"8. 의문문","depth":2},{"id":"reading-21","label":"must","depth":2},{"id":"reading-22","label":"have to","depth":2},{"id":"reading-23","label":"9. 과거에서는 had to","depth":2},{"id":"reading-24","label":"10. 미래에서도 have to","depth":2},{"id":"reading-25","label":"핵심 비교","depth":2},{"id":"reading-26","label":"문장 구조","depth":2},{"id":"reading-27","label":"must","depth":3},{"id":"reading-28","label":"have to","depth":3},{"id":"reading-29","label":"연습","depth":2}],"origin":"conversation","characters":3248,"aliases":{"structure":"reading-26","examples":"reading-9","contrast":"reading-6","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-6","topic-5":"reading-9","topic-6":"reading-10","topic-7":"reading-11","topic-8":"reading-12","topic-9":"reading-13","topic-10":"reading-14","topic-11":"reading-17","topic-12":"reading-20"}},{"id":25,"title":"25단계 — may / might","html":"\u003ch1 id=\"lesson-title\" data-id=\"25\">25단계 — \u003ccode>may / might\u003c/code>\u003c/h1>\n\u003cp>둘 다 기본적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~일 수도 있다 / ~할지도 모른다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 \u003cstrong>가능성\u003c/strong>을 나타낸다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + may/might + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>It \u003cstrong>may rain\u003c/strong> tomorrow.\u003cbr>내일 비가 올 수도 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>might come\u003c/strong> later.\u003cbr>그녀가 나중에 올지도 모른다.\u003c/p>\n\u003c/blockquote>\n\u003cp>중요한 규칙:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>may / might 뒤에는 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ She may comes.\u003cbr>✅ She may come.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>may\u003c/code>의 기본 의미\u003c/h2>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">가능성\u003c/h3>\n\u003cblockquote>\n\u003cp>He \u003cstrong>may be\u003c/strong> busy.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 바쁠 수도 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We \u003cstrong>may go\u003c/strong> there tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>우리는 내일 거기에 갈 수도 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>아직 확실하지 않다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">3. \u003ccode>might\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>might\u003c/code>도 거의 같은 의미다.\u003c/p>\n\u003cblockquote>\n\u003cp>It \u003cstrong>might rain\u003c/strong> tonight.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>오늘 밤 비가 올지도 모른다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>might know\u003c/strong> the answer.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 답을 알고 있을지도 모른다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">4. \u003ccode>may\u003c/code>와 \u003ccode>might\u003c/code>의 차이\u003c/h2>\n\u003cp>전통적으로는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>may = 가능성이 조금 더 있음\u003c/strong>\u003cbr>\u003cstrong>might = 가능성이 조금 더 낮음\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이라고 설명하기도 한다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>It may rain.\u003c/p>\n\u003c/blockquote>\n\u003cp>비가 올 수도 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>It might rain.\u003c/p>\n\u003c/blockquote>\n\u003cp>비가 올지도 모르겠다.\u003c/p>\n\u003cp>하지만 실제 회화에서는 이 차이가 \u003cstrong>명확하지 않은 경우가 많다.\u003c/strong>\u003c/p>\n\u003cp>둘 다:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>확실하지 않은 가능성\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>을 표현한다고 이해하는 게 먼저다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">5. 중요한 감각\u003c/h2>\n\u003cp>\u003ccode>will\u003c/code>과 비교하면 훨씬 쉽게 이해된다.\u003c/p>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">will\u003c/h3>\n\u003cblockquote>\n\u003cp>It \u003cstrong>will rain\u003c/strong> tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내일 비가 올 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>말하는 사람이 상당히 확신한다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">may\u003c/h3>\n\u003cblockquote>\n\u003cp>It \u003cstrong>may rain\u003c/strong> tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내일 비가 올 수도 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>확실하지 않다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">might\u003c/h3>\n\u003cblockquote>\n\u003cp>It \u003cstrong>might rain\u003c/strong> tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>내일 비가 올지도 모른다.\u003c/p>\n\u003c/blockquote>\n\u003cp>역시 확실하지 않다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">6. \u003ccode>be\u003c/code>와도 자주 사용\u003c/h2>\n\u003cp>조동사 뒤에는 동사원형이므로 \u003ccode>be\u003c/code>를 그대로 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>may be tired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>She / may / be / tired\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>She = 주어\u003c/li>\n\u003cli>may = 조동사\u003c/li>\n\u003cli>be = 동사원형\u003c/li>\n\u003cli>tired = 형용사\u003c/li>\n\u003c/ul>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ She may is tired.\u003cbr>✅ She may be tired.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 형태는 매우 중요하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">비교\u003c/h2>\n\u003cp>평범한 문장:\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>is\u003c/strong> tired.\u003c/p>\n\u003c/blockquote>\n\u003cp>가능성을 넣으면:\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>may be\u003c/strong> tired.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>is\u003c/code>가 \u003ccode>be\u003c/code>로 바뀐다.\u003c/p>\n\u003cp>왜냐하면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>조동사 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>규칙 때문이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">7. 일반동사도 동일\u003c/h2>\n\u003cblockquote>\n\u003cp>He works today.\u003c/p>\n\u003c/blockquote>\n\u003cp>가능성:\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>may work\u003c/strong> today.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>works → work\u003c/code>\u003c/p>\n\u003cblockquote>\n\u003cp>❌ He may works today.\u003cbr>✅ He may work today.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">8. 부정문\u003c/h2>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">may not\u003c/h3>\n\u003cblockquote>\n\u003cp>She \u003cstrong>may not come\u003c/strong> today.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>그녀가 오늘 \u003cstrong>오지 않을 수도 있다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>may not\u003c/code>은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>금지\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>가 아니라 문맥에 따라 \u003cstrong>가능성의 부정\u003c/strong>이 될 수 있다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">might not\u003c/h3>\n\u003cblockquote>\n\u003cp>He \u003cstrong>might not know\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그가 모를 수도 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>may/might + not + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">9. \u003ccode>may not\u003c/code>의 두 가지 의미\u003c/h2>\n\u003cp>\u003ccode>may\u003c/code>에는 \u003cstrong>허락\u003c/strong>의 의미도 있기 때문에 주의해야 한다.\u003c/p>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">가능성\u003c/h3>\n\u003cblockquote>\n\u003cp>She may not come.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀가 안 올 수도 있다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">허락하지 않음\u003c/h3>\n\u003cblockquote>\n\u003cp>You may not enter.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>들어가면 안 됩니다.\u003c/p>\n\u003c/blockquote>\n\u003cp>문맥에 따라 의미가 달라진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">10. \u003ccode>may\u003c/code>로 허락을 물을 수도 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>May I come in?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>들어가도 될까요?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>Can I come in?\u003c/code>보다 보통 더 \u003cstrong>격식 있고 공손한 표현\u003c/strong>이다.\u003c/p>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">일상적인 표현\u003c/h3>\n\u003cblockquote>\n\u003cp>Can I sit here?\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">좀 더 격식 있는 표현\u003c/h3>\n\u003cblockquote>\n\u003cp>May I sit here?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">11. \u003ccode>might\u003c/code>는 보통 허락에 쓰지 않는다\u003c/h2>\n\u003cp>초급에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>may → 가능성 + 허락\u003cbr>might → 주로 가능성\u003c/p>\n\u003c/blockquote>\n\u003cp>으로 구분하면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">12. 질문 형태\u003c/h2>\n\u003cp>가능성을 묻는 질문에서는 \u003ccode>may/might\u003c/code>를 바로 앞으로 보내는 형태가 문법적으로 가능하지만, 일상에서는 그렇게 자주 쓰지 않는 경우가 많다.\u003c/p>\n\u003cp>예를 들어:\u003c/p>\n\u003cblockquote>\n\u003cp>그가 올 수도 있을까?\u003c/p>\n\u003c/blockquote>\n\u003cp>보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Do you think he might come?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>같은 표현이 더 자연스럽다.\u003c/p>\n\u003cp>이 부분은 이후 의문문 확장 단계에서 다룬다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-24\" data-reading-anchor=\"reading-24\">13. 지금까지 조동사 정리\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>조동사\u003c/th>\n\u003cth>기본 의미\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>can\u003c/td>\n\u003ctd>~할 수 있다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>will\u003c/td>\n\u003ctd>~할 것이다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>should\u003c/td>\n\u003ctd>~하는 게 좋다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>must\u003c/td>\n\u003ctd>반드시 ~해야 한다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>may\u003c/td>\n\u003ctd>~일 수도 있다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>might\u003c/td>\n\u003ctd>~일지도 모른다\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>공통 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>조동사 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>can go\u003cbr>will go\u003cbr>should go\u003cbr>must go\u003cbr>may go\u003cbr>might go\u003c/p>\n\u003c/blockquote>\n\u003cp>전부 똑같은 구조다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-25\" data-reading-anchor=\"reading-25\">핵심\u003c/h2>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">가능성\u003c/h3>\n\u003cblockquote>\n\u003cp>She \u003cstrong>may come\u003c/strong>.\u003cbr>그녀가 올 수도 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>might come\u003c/strong>.\u003cbr>그녀가 올지도 모른다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-27\" data-reading-anchor=\"reading-27\">상태의 가능성\u003c/h3>\n\u003cblockquote>\n\u003cp>She \u003cstrong>may be tired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-28\" data-reading-anchor=\"reading-28\">부정 가능성\u003c/h3>\n\u003cblockquote>\n\u003cp>She \u003cstrong>might not come\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고 항상:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>may/might + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-29\" data-reading-anchor=\"reading-29\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>She may \u003cstrong>come / comes\u003c/strong> later.\u003c/li>\n\u003cli>He might \u003cstrong>be / is\u003c/strong> tired.\u003c/li>\n\u003cli>It may \u003cstrong>rain / rains\u003c/strong> tomorrow.\u003c/li>\n\u003cli>She \u003cstrong>might not come / doesn&#39;t might come\u003c/strong> today.\u003c/li>\n\u003cli>He may \u003cstrong>know / knows\u003c/strong> the answer.\u003c/li>\n\u003cli>\u003cstrong>May I / Do I may\u003c/strong> sit here?\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>26단계 — 비교급 \u003ccode>bigger / more beautiful\u003c/code>\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 구조","depth":2},{"id":"reading-2","label":"2. may의 기본 의미","depth":2},{"id":"reading-3","label":"가능성","depth":3},{"id":"reading-4","label":"3. might","depth":2},{"id":"reading-5","label":"4. may와 might의 차이","depth":2},{"id":"reading-6","label":"5. 중요한 감각","depth":2},{"id":"reading-7","label":"will","depth":3},{"id":"reading-8","label":"may","depth":3},{"id":"reading-9","label":"might","depth":3},{"id":"reading-10","label":"6. be와도 자주 사용","depth":2},{"id":"reading-11","label":"비교","depth":2},{"id":"reading-12","label":"7. 일반동사도 동일","depth":2},{"id":"reading-13","label":"8. 부정문","depth":2},{"id":"reading-14","label":"may not","depth":3},{"id":"reading-15","label":"might not","depth":3},{"id":"reading-16","label":"9. may not의 두 가지 의미","depth":2},{"id":"reading-17","label":"가능성","depth":3},{"id":"reading-18","label":"허락하지 않음","depth":3},{"id":"reading-19","label":"10. may로 허락을 물을 수도 있다","depth":2},{"id":"reading-20","label":"일상적인 표현","depth":3},{"id":"reading-21","label":"좀 더 격식 있는 표현","depth":3},{"id":"reading-22","label":"11. might는 보통 허락에 쓰지 않는다","depth":2},{"id":"reading-23","label":"12. 질문 형태","depth":2},{"id":"reading-24","label":"13. 지금까지 조동사 정리","depth":2},{"id":"reading-25","label":"핵심","depth":2},{"id":"reading-26","label":"가능성","depth":3},{"id":"reading-27","label":"상태의 가능성","depth":3},{"id":"reading-28","label":"부정 가능성","depth":3},{"id":"reading-29","label":"연습","depth":2}],"origin":"conversation","characters":3342,"aliases":{"structure":"reading-1","examples":"concept","contrast":"reading-5","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-4","topic-4":"reading-5","topic-5":"reading-6","topic-6":"reading-10","topic-7":"reading-11","topic-8":"reading-12","topic-9":"reading-13","topic-10":"reading-16","topic-11":"reading-19","topic-12":"reading-22"}},{"id":26,"title":"26단계 — 비교급 -er / more","html":"\u003ch1 id=\"lesson-title\" data-id=\"26\">26단계 — 비교급 \u003ccode>-er / more\u003c/code>\u003c/h1>\n\u003cp>비교급은 \u003cstrong>두 대상을 비교해서 “더 ~하다”\u003c/strong>라고 말할 때 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>A + be동사 + 비교급 + than + B\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>Tom is \u003cstrong>taller than\u003c/strong> John.\u003cbr>톰은 존보다 더 크다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cul>\n\u003cli>Tom = 비교 대상 A\u003c/li>\n\u003cli>is = be동사\u003c/li>\n\u003cli>taller = 더 큰\u003c/li>\n\u003cli>than John = 존보다\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 짧은 형용사 → \u003ccode>-er\u003c/code>\u003c/h2>\n\u003cp>보통 짧은 형용사는 뒤에 \u003ccode>-er\u003c/code>를 붙인다.\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>원형\u003c/th>\n\u003cth>비교급\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>tall\u003c/td>\n\u003ctd>taller\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>small\u003c/td>\n\u003ctd>smaller\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>fast\u003c/td>\n\u003ctd>faster\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>old\u003c/td>\n\u003ctd>older\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>young\u003c/td>\n\u003ctd>younger\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>My car is \u003cstrong>faster than\u003c/strong> yours.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Narin is \u003cstrong>taller than\u003c/strong> before.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 긴 형용사 → \u003ccode>more + 형용사\u003c/code>\u003c/h2>\n\u003cp>비교적 긴 형용사는 \u003ccode>-er\u003c/code> 대신:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>more + 형용사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 사용한다.\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>원형\u003c/th>\n\u003cth>비교급\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>beautiful\u003c/td>\n\u003ctd>more beautiful\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>expensive\u003c/td>\n\u003ctd>more expensive\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>popular\u003c/td>\n\u003ctd>more popular\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>comfortable\u003c/td>\n\u003ctd>more comfortable\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>interesting\u003c/td>\n\u003ctd>more interesting\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>This hotel is \u003cstrong>more expensive than\u003c/strong> that one.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>This book is \u003cstrong>more interesting than\u003c/strong> that book.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. 왜 \u003ccode>taller\u003c/code>인데 \u003ccode>more popular\u003c/code>인가?\u003c/h2>\n\u003cp>이전에 헷갈렸던 부분과 연결된다.\u003c/p>\n\u003cp>\u003ccode>tall\u003c/code>은 짧은 형용사라:\u003c/p>\n\u003cblockquote>\n\u003cp>tall → taller\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ She is taller than me.\u003c/p>\n\u003c/blockquote>\n\u003cp>이미 \u003ccode>taller\u003c/code> 자체에 \u003cstrong>“더”\u003c/strong>라는 의미가 들어 있다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ She is more taller than me.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>more + taller\u003c/code>는 \u003cstrong>“더 더 크다”\u003c/strong>처럼 비교 표현이 중복된다.\u003c/p>\n\u003chr>\n\u003cp>반면 \u003ccode>popular\u003c/code>는 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>popular → more popular\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ She is more popular than me.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ She is popularer than me.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. 철자가 조금 변하는 경우\u003c/h2>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">\u003ccode>e\u003c/code>로 끝나면 \u003ccode>-r\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>large → larger\u003cbr>nice → nicer\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">짧은 단어에서 마지막 자음을 한 번 더\u003c/h3>\n\u003cblockquote>\n\u003cp>big → bigger\u003cbr>hot → hotter\u003cbr>thin → thinner\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">\u003ccode>자음 + y\u003c/code>\u003c/h3>\n\u003cp>\u003ccode>y → i\u003c/code> 후 \u003ccode>-er\u003c/code>\u003c/p>\n\u003cblockquote>\n\u003cp>happy → happier\u003cbr>easy → easier\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>She looks \u003cstrong>happier\u003c/strong> today.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">6. 불규칙 비교급\u003c/h2>\n\u003cp>규칙대로 만들 수 없는 단어도 있다.\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>원형\u003c/th>\n\u003cth>비교급\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>good\u003c/td>\n\u003ctd>better\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>bad\u003c/td>\n\u003ctd>worse\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>far\u003c/td>\n\u003ctd>farther / further\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>This one is \u003cstrong>better\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Today is \u003cstrong>worse than\u003c/strong> yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ gooder\u003cbr>✅ better\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">7. \u003ccode>than\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>than\u003c/code>은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~보다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이다.\u003c/p>\n\u003cblockquote>\n\u003cp>bigger \u003cstrong>than\u003c/strong>\u003cbr>더 크다 + ~보다\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>cheaper \u003cstrong>than\u003c/strong>\u003cbr>더 싸다 + ~보다\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>more expensive \u003cstrong>than\u003c/strong>\u003cbr>더 비싸다 + ~보다\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">8. 비교급만 말할 수도 있다\u003c/h2>\n\u003cp>비교 대상이 이미 명확하면 \u003ccode>than\u003c/code> 뒤를 생략할 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>This one is better.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이게 더 좋아.\u003c/p>\n\u003c/blockquote>\n\u003cp>무엇보다 좋은지는 상황상 알고 있는 경우다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">9. 일반동사와도 사용할 수 있다\u003c/h2>\n\u003cp>비교급이 반드시 be동사하고만 쓰이는 건 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>She runs \u003cstrong>faster than\u003c/strong> me.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 나보다 더 빨리 달린다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 \u003ccode>faster\u003c/code>가 \u003ccode>runs\u003c/code>를 설명한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">10. \u003ccode>much / a lot / way + 비교급\u003c/code>\u003c/h2>\n\u003cp>비교급을 더 강조할 수도 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>much better\u003cbr>a lot better\u003cbr>way better\u003c/p>\n\u003c/blockquote>\n\u003cp>전부:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>훨씬 더 좋다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>This is \u003cstrong>much better\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>This is \u003cstrong>way better\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>way\u003c/code>가 여기서 \u003cstrong>훨씬\u003c/strong>이라는 뜻으로 쓰이는 이유다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">핵심\u003c/h2>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">짧은 형용사\u003c/h3>\n\u003cblockquote>\n\u003cp>tall → \u003cstrong>taller\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">긴 형용사\u003c/h3>\n\u003cblockquote>\n\u003cp>popular → \u003cstrong>more popular\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ taller\u003cbr>❌ more taller\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ more popular\u003c/p>\n\u003c/blockquote>\n\u003cp>기본 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>A + be동사 + 비교급 + than + B\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>She is \u003cstrong>taller / more taller\u003c/strong> than me.\u003c/li>\n\u003cli>This car is \u003cstrong>expensiver / more expensive\u003c/strong>.\u003c/li>\n\u003cli>My house is \u003cstrong>bigger / more big\u003c/strong> than yours.\u003c/li>\n\u003cli>This movie is \u003cstrong>more interesting / interestinger\u003c/strong>.\u003c/li>\n\u003cli>Today is \u003cstrong>better / gooder\u003c/strong> than yesterday.\u003c/li>\n\u003cli>This phone is \u003cstrong>way better / way good\u003c/strong> than my old one.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>27단계 — 최상급 \u003ccode>the biggest / the most beautiful\u003c/code>\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 구조","depth":2},{"id":"reading-2","label":"2. 짧은 형용사 → -er","depth":2},{"id":"reading-3","label":"3. 긴 형용사 → more + 형용사","depth":2},{"id":"reading-4","label":"4. 왜 taller인데 more popular인가?","depth":2},{"id":"reading-5","label":"5. 철자가 조금 변하는 경우","depth":2},{"id":"reading-6","label":"e로 끝나면 -r","depth":3},{"id":"reading-7","label":"짧은 단어에서 마지막 자음을 한 번 더","depth":3},{"id":"reading-8","label":"자음 + y","depth":3},{"id":"reading-9","label":"6. 불규칙 비교급","depth":2},{"id":"reading-10","label":"7. than","depth":2},{"id":"reading-11","label":"8. 비교급만 말할 수도 있다","depth":2},{"id":"reading-12","label":"9. 일반동사와도 사용할 수 있다","depth":2},{"id":"reading-13","label":"10. much / a lot / way + 비교급","depth":2},{"id":"reading-14","label":"핵심","depth":2},{"id":"reading-15","label":"짧은 형용사","depth":3},{"id":"reading-16","label":"긴 형용사","depth":3},{"id":"reading-17","label":"연습","depth":2}],"origin":"conversation","characters":2950,"aliases":{"structure":"reading-1","examples":"concept","contrast":"reading-9","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-9","topic-7":"reading-10","topic-8":"reading-11","topic-9":"reading-12","topic-10":"reading-13","topic-11":"reading-14","topic-12":"reading-17"}},{"id":27,"title":"27단계 — 최상급 the -est / the most","html":"\u003ch1 id=\"lesson-title\" data-id=\"27\">27단계 — 최상급 \u003ccode>the -est / the most\u003c/code>\u003c/h1>\n\u003cp>최상급은 \u003cstrong>셋 이상을 비교해서 “가장 ~하다”\u003c/strong>라고 말할 때 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>A + be동사 + the + 최상급\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>Tom is \u003cstrong>the tallest\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>톰이 가장 크다.\u003c/p>\n\u003c/blockquote>\n\u003cp>비교 범위를 넣으면:\u003c/p>\n\u003cblockquote>\n\u003cp>Tom is \u003cstrong>the tallest in the class\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>톰은 반에서 가장 크다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 짧은 형용사 → \u003ccode>-est\u003c/code>\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>원형\u003c/th>\n\u003cth>비교급\u003c/th>\n\u003cth>최상급\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>tall\u003c/td>\n\u003ctd>taller\u003c/td>\n\u003ctd>tallest\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>small\u003c/td>\n\u003ctd>smaller\u003c/td>\n\u003ctd>smallest\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>fast\u003c/td>\n\u003ctd>faster\u003c/td>\n\u003ctd>fastest\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>old\u003c/td>\n\u003ctd>older\u003c/td>\n\u003ctd>oldest\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>He is \u003cstrong>the tallest\u003c/strong> boy here.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>This is \u003cstrong>the smallest\u003c/strong> room.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 긴 형용사 → \u003ccode>the most + 형용사\u003c/code>\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>원형\u003c/th>\n\u003cth>비교급\u003c/th>\n\u003cth>최상급\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>beautiful\u003c/td>\n\u003ctd>more beautiful\u003c/td>\n\u003ctd>most beautiful\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>expensive\u003c/td>\n\u003ctd>more expensive\u003c/td>\n\u003ctd>most expensive\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>popular\u003c/td>\n\u003ctd>more popular\u003c/td>\n\u003ctd>most popular\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>interesting\u003c/td>\n\u003ctd>more interesting\u003c/td>\n\u003ctd>most interesting\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>This is \u003cstrong>the most expensive\u003c/strong> car.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>the most popular\u003c/strong> student.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. 비교급과 최상급 연결\u003c/h2>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">원급\u003c/h3>\n\u003cblockquote>\n\u003cp>tall\u003cbr>큰\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">비교급\u003c/h3>\n\u003cblockquote>\n\u003cp>taller\u003cbr>더 큰\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">최상급\u003c/h3>\n\u003cblockquote>\n\u003cp>tallest\u003cbr>가장 큰\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>Tom is tall.\u003cbr>Tom is taller than John.\u003cbr>Tom is the tallest in the class.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. 왜 \u003ccode>the\u003c/code>가 붙는가?\u003c/h2>\n\u003cp>최상급은 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>그 집단에서 딱 하나의 가장 ~한 대상\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>을 말한다.\u003c/p>\n\u003cp>그래서 보통 \u003ccode>the\u003c/code>를 붙인다.\u003c/p>\n\u003cblockquote>\n\u003cp>the biggest\u003cbr>the best\u003cbr>the most expensive\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">6. 철자 변화\u003c/h2>\n\u003cp>비교급에서 배운 규칙과 거의 같다.\u003c/p>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">\u003ccode>e\u003c/code>로 끝남\u003c/h3>\n\u003cblockquote>\n\u003cp>large → largest\u003cbr>nice → nicest\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">짧은 단어\u003c/h3>\n\u003cp>마지막 자음을 한 번 더:\u003c/p>\n\u003cblockquote>\n\u003cp>big → biggest\u003cbr>hot → hottest\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">자음 + y\u003c/h3>\n\u003cblockquote>\n\u003cp>happy → happiest\u003cbr>easy → easiest\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">7. 불규칙 최상급\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>원형\u003c/th>\n\u003cth>비교급\u003c/th>\n\u003cth>최상급\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>good\u003c/td>\n\u003ctd>better\u003c/td>\n\u003ctd>best\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>bad\u003c/td>\n\u003ctd>worse\u003c/td>\n\u003ctd>worst\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>far\u003c/td>\n\u003ctd>farther/further\u003c/td>\n\u003ctd>farthest/furthest\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>This is \u003cstrong>the best\u003c/strong> one.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>That was \u003cstrong>the worst\u003c/strong> day.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">8. 비교 범위 \u003ccode>in / of\u003c/code>\u003c/h2>\n\u003cp>이 부분이 중요하다.\u003c/p>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">\u003ccode>in + 장소/집단\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>the tallest \u003cstrong>in the class\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>the biggest building \u003cstrong>in Busan\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">\u003ccode>of + 여러 대상\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>the tallest \u003cstrong>of the three\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>the best \u003cstrong>of them\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>기본 감각:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>in = 어떤 공간·집단 안에서\u003c/strong>\u003cbr>\u003cstrong>of = 몇 개의 대상 중에서\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">9. \u003ccode>one of the + 최상급 + 복수명사\u003c/code>\u003c/h2>\n\u003cp>아주 자주 쓰는 구조다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>one of the best restaurants\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>최고의 식당들 중 하나\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 중요한 점:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>one of the + 최상급 + 복수명사\u003c/code>\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ one of the best restaurant\u003cbr>✅ one of the best restaurants\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">10. 비교급과 최상급 차이\u003c/h2>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">둘 비교\u003c/h3>\n\u003cblockquote>\n\u003cp>A is \u003cstrong>bigger than\u003c/strong> B.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">셋 이상 중 최고\u003c/h3>\n\u003cblockquote>\n\u003cp>A is \u003cstrong>the biggest\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">핵심\u003c/h2>\n\u003cp>짧은 형용사:\u003c/p>\n\u003cblockquote>\n\u003cp>tall → taller → \u003cstrong>the tallest\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>긴 형용사:\u003c/p>\n\u003cblockquote>\n\u003cp>beautiful → more beautiful → \u003cstrong>the most beautiful\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>불규칙:\u003c/p>\n\u003cblockquote>\n\u003cp>good → better → \u003cstrong>the best\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>She is \u003cstrong>the tallest / the most tall\u003c/strong> in the class.\u003c/li>\n\u003cli>This is \u003cstrong>the most expensive / the expensivest\u003c/strong> car.\u003c/li>\n\u003cli>He is \u003cstrong>the best / the goodest\u003c/strong> player.\u003c/li>\n\u003cli>This is \u003cstrong>the biggest / the most big\u003c/strong> room.\u003c/li>\n\u003cli>She is one of \u003cstrong>the best students / the best student\u003c/strong> in the class.\u003c/li>\n\u003cli>This is \u003cstrong>the most interesting / the interestinger\u003c/strong> book here.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>28단계 — 전치사 \u003ccode>in / on / at\u003c/code>의 기본 개념\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 구조","depth":2},{"id":"reading-2","label":"2. 짧은 형용사 → -est","depth":2},{"id":"reading-3","label":"3. 긴 형용사 → the most + 형용사","depth":2},{"id":"reading-4","label":"4. 비교급과 최상급 연결","depth":2},{"id":"reading-5","label":"원급","depth":3},{"id":"reading-6","label":"비교급","depth":3},{"id":"reading-7","label":"최상급","depth":3},{"id":"reading-8","label":"5. 왜 the가 붙는가?","depth":2},{"id":"reading-9","label":"6. 철자 변화","depth":2},{"id":"reading-10","label":"e로 끝남","depth":3},{"id":"reading-11","label":"짧은 단어","depth":3},{"id":"reading-12","label":"자음 + y","depth":3},{"id":"reading-13","label":"7. 불규칙 최상급","depth":2},{"id":"reading-14","label":"8. 비교 범위 in / of","depth":2},{"id":"reading-15","label":"in + 장소/집단","depth":3},{"id":"reading-16","label":"of + 여러 대상","depth":3},{"id":"reading-17","label":"9. one of the + 최상급 + 복수명사","depth":2},{"id":"reading-18","label":"10. 비교급과 최상급 차이","depth":2},{"id":"reading-19","label":"둘 비교","depth":3},{"id":"reading-20","label":"셋 이상 중 최고","depth":3},{"id":"reading-21","label":"핵심","depth":2},{"id":"reading-22","label":"연습","depth":2}],"origin":"conversation","characters":2722,"aliases":{"structure":"reading-1","examples":"concept","contrast":"reading-4","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-8","topic-6":"reading-9","topic-7":"reading-13","topic-8":"reading-14","topic-9":"reading-17","topic-10":"reading-18","topic-11":"reading-21","topic-12":"reading-22"}},{"id":28,"title":"28단계 — 전치사 in / on / at","html":"\u003ch1 id=\"lesson-title\" data-id=\"28\">28단계 — 전치사 \u003ccode>in / on / at\u003c/code>\u003c/h1>\n\u003cp>전치사는 \u003cstrong>명사 앞에 붙어서 위치·시간·방향 같은 관계를 보여주는 말\u003c/strong>이다.\u003c/p>\n\u003cp>이번에는 가장 기본적인:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>in / on / at\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>세 개만 배운다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 가장 큰 감각\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">\u003ccode>in\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>안에\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">\u003ccode>on\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>표면 위에\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">\u003ccode>at\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>한 지점에\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>먼저 공간 개념부터 잡는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">2. \u003ccode>in\u003c/code> — 안에\u003c/h2>\n\u003cp>어떤 공간의 \u003cstrong>내부\u003c/strong>에 있다는 느낌이다.\u003c/p>\n\u003cblockquote>\n\u003cp>in the room\u003cbr>방 안에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>in the car\u003cbr>차 안에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>in the box\u003cbr>상자 안에\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>in the room\u003c/strong>.\u003cbr>그녀는 방 안에 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>The keys are \u003cstrong>in the bag\u003c/strong>.\u003cbr>열쇠는 가방 안에 있다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">3. 큰 지역도 \u003ccode>in\u003c/code>\u003c/h2>\n\u003cp>도시나 나라처럼 \u003cstrong>넓은 공간 안에 있다\u003c/strong>고 생각한다.\u003c/p>\n\u003cblockquote>\n\u003cp>in Busan\u003cbr>부산에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>in Korea\u003cbr>한국에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>in Japan\u003cbr>일본에\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I live \u003cstrong>in Busan\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 부산을 하나의 넓은 영역으로 보는 것이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">4. \u003ccode>on\u003c/code> — 표면 위에\u003c/h2>\n\u003cp>어떤 표면에 \u003cstrong>닿아 있는 느낌\u003c/strong>이다.\u003c/p>\n\u003cblockquote>\n\u003cp>on the table\u003cbr>탁자 위에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>on the wall\u003cbr>벽에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>on the floor\u003cbr>바닥에\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>My phone is \u003cstrong>on the table\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>There is a picture \u003cstrong>on the wall\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>벽은 세로지만 \u003ccode>on\u003c/code>을 쓴다.\u003c/p>\n\u003cp>중요한 것은:\u003c/p>\n\u003cblockquote>\n\u003cp>위쪽 방향 ❌\u003cbr>\u003cstrong>표면에 닿아 있음\u003c/strong> ✅\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. \u003ccode>at\u003c/code> — 한 지점\u003c/h2>\n\u003cp>\u003ccode>at\u003c/code>은 공간을 넓게 보기보다 \u003cstrong>하나의 위치 지점\u003c/strong>으로 본다.\u003c/p>\n\u003cblockquote>\n\u003cp>at home\u003cbr>집에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>at work\u003cbr>직장에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>at school\u003cbr>학교에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>at the bus stop\u003cbr>버스 정류장에\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>at home\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She&#39;s \u003cstrong>at work\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">6. \u003ccode>in\u003c/code>과 \u003ccode>at\u003c/code>의 차이\u003c/h2>\n\u003cp>둘 다 한국어로는 흔히 “~에”라고 번역된다.\u003c/p>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">\u003ccode>in\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>I am \u003cstrong>in the office\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>사무실 \u003cstrong>내부에 있다\u003c/strong>는 공간적 의미.\u003c/p>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">\u003ccode>at\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>I am \u003cstrong>at the office\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>사무실이라는 \u003cstrong>장소에 있다\u003c/strong>는 의미.\u003c/p>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>in\u003c/code> = 내부 공간 강조\u003cbr>\u003ccode>at\u003c/code> = 위치 지점 강조\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">7. 학교도 마찬가지\u003c/h2>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>at school\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>학교에 있다.\u003c/p>\n\u003cp>학교라는 장소 또는 활동을 중심으로 본다.\u003c/p>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>in the school\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>학교 건물 \u003cstrong>안에\u003c/strong> 있다.\u003c/p>\n\u003cp>건물 내부라는 공간을 강조한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">8. 시간에서도 같은 감각이 이어진다\u003c/h2>\n\u003cp>전치사는 장소뿐 아니라 \u003cstrong>시간\u003c/strong>에도 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">\u003ccode>at\u003c/code> — 정확한 시점\u003c/h2>\n\u003cblockquote>\n\u003cp>at 7 o&#39;clock\u003cbr>7시에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>at noon\u003cbr>정오에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>at midnight\u003cbr>자정에\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I get up \u003cstrong>at 7\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>7시\u003c/code>라는 하나의 정확한 지점을 찍는 느낌이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">9. \u003ccode>on\u003c/code> — 특정한 날\u003c/h2>\n\u003cblockquote>\n\u003cp>on Monday\u003cbr>월요일에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>on Friday\u003cbr>금요일에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>on September 11\u003cbr>9월 11일에\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I work \u003cstrong>on Monday\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>하루라는 시간 단위를 하나의 면처럼 본다고 생각하면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">10. \u003ccode>in\u003c/code> — 넓은 시간 범위\u003c/h2>\n\u003cblockquote>\n\u003cp>in September\u003cbr>9월에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>in 2026\u003cbr>2026년에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>in summer\u003cbr>여름에\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>in the morning\u003cbr>아침에\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I was born \u003cstrong>in 1984\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We travel \u003cstrong>in summer\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">11. 시간 전치사 정리\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>전치사\u003c/th>\n\u003cth>감각\u003c/th>\n\u003cth>예\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>at\u003c/td>\n\u003ctd>정확한 시점\u003c/td>\n\u003ctd>at 7\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>on\u003c/td>\n\u003ctd>특정한 날\u003c/td>\n\u003ctd>on Monday\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>in\u003c/td>\n\u003ctd>넓은 기간\u003c/td>\n\u003ctd>in September\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>at 7 p.m.\u003c/strong>\u003cbr>\u003cstrong>on Monday\u003c/strong>\u003cbr>\u003cstrong>in September\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>순서대로 시간 범위가 점점 넓어진다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">12. 자주 헷갈리는 표현\u003c/h2>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">아침\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>in the morning\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">오후\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>in the afternoon\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">저녁\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>in the evening\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>at night\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이건 관용적으로 \u003ccode>at\u003c/code>을 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">13. 핵심\u003c/h2>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">장소\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>in\u003c/strong> = 공간 안\u003cbr>\u003cstrong>on\u003c/strong> = 표면\u003cbr>\u003cstrong>at\u003c/strong> = 지점\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>in the room\u003cbr>on the table\u003cbr>at school\u003c/p>\n\u003c/blockquote>\n\u003ch2 id=\"reading-24\" data-reading-anchor=\"reading-24\">시간\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>at\u003c/strong> = 시각\u003cbr>\u003cstrong>on\u003c/strong> = 날짜·요일\u003cbr>\u003cstrong>in\u003c/strong> = 월·연도·계절\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>at 8\u003cbr>on Friday\u003cbr>in September\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-25\" data-reading-anchor=\"reading-25\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I live \u003cstrong>in / at\u003c/strong> Busan.\u003c/li>\n\u003cli>My phone is \u003cstrong>in / on\u003c/strong> the table.\u003c/li>\n\u003cli>She is \u003cstrong>at / on\u003c/strong> work.\u003c/li>\n\u003cli>I get up \u003cstrong>at / in\u003c/strong> 7 a.m.\u003c/li>\n\u003cli>We have a meeting \u003cstrong>on / in\u003c/strong> Monday.\u003c/li>\n\u003cli>I was born \u003cstrong>in / on\u003c/strong> 1984.\u003c/li>\n\u003cli>The keys are \u003cstrong>in / on\u003c/strong> my bag.\u003c/li>\n\u003cli>I usually study \u003cstrong>at / in\u003c/strong> night.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>29단계 — 방향 전치사 \u003ccode>to / from / into / out of\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 가장 큰 감각","depth":2},{"id":"reading-2","label":"in","depth":3},{"id":"reading-3","label":"on","depth":3},{"id":"reading-4","label":"at","depth":3},{"id":"reading-5","label":"2. in — 안에","depth":2},{"id":"reading-6","label":"3. 큰 지역도 in","depth":2},{"id":"reading-7","label":"4. on — 표면 위에","depth":2},{"id":"reading-8","label":"5. at — 한 지점","depth":2},{"id":"reading-9","label":"6. in과 at의 차이","depth":2},{"id":"reading-10","label":"in","depth":3},{"id":"reading-11","label":"at","depth":3},{"id":"reading-12","label":"7. 학교도 마찬가지","depth":2},{"id":"reading-13","label":"8. 시간에서도 같은 감각이 이어진다","depth":2},{"id":"reading-14","label":"at — 정확한 시점","depth":2},{"id":"reading-15","label":"9. on — 특정한 날","depth":2},{"id":"reading-16","label":"10. in — 넓은 시간 범위","depth":2},{"id":"reading-17","label":"11. 시간 전치사 정리","depth":2},{"id":"reading-18","label":"12. 자주 헷갈리는 표현","depth":2},{"id":"reading-19","label":"아침","depth":3},{"id":"reading-20","label":"오후","depth":3},{"id":"reading-21","label":"저녁","depth":3},{"id":"reading-22","label":"13. 핵심","depth":2},{"id":"reading-23","label":"장소","depth":2},{"id":"reading-24","label":"시간","depth":2},{"id":"reading-25","label":"연습","depth":2}],"origin":"conversation","characters":2923,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-9","topic-1":"reading-1","topic-2":"reading-5","topic-3":"reading-6","topic-4":"reading-7","topic-5":"reading-8","topic-6":"reading-9","topic-7":"reading-12","topic-8":"reading-13","topic-9":"reading-14","topic-10":"reading-15","topic-11":"reading-16","topic-12":"reading-17"}},{"id":29,"title":"29단계 — 방향 전치사 to / from / into / out of","html":"\u003ch1 id=\"lesson-title\" data-id=\"29\">29단계 — 방향 전치사 \u003ccode>to / from / into / out of\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>어디로 움직이는지\u003c/strong>를 나타내는 전치사를 배운다.\u003c/p>\n\u003cp>핵심은 네 가지다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>to = ~로\u003c/strong>\u003cbr>\u003cstrong>from = ~에서부터\u003c/strong>\u003cbr>\u003cstrong>into = ~안으로\u003c/strong>\u003cbr>\u003cstrong>out of = ~밖으로\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>to\u003c/code> — 목적지로\u003c/h2>\n\u003cp>\u003ccode>to\u003c/code>는 \u003cstrong>어디를 향해 이동하는지\u003c/strong>를 나타낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>go \u003cstrong>to school\u003c/strong>\u003cbr>학교에 가다\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>come \u003cstrong>to my house\u003c/strong>\u003cbr>우리 집으로 오다\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>drive \u003cstrong>to work\u003c/strong>\u003cbr>직장으로 운전해서 가다\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I go \u003cstrong>to work\u003c/strong> every morning.\u003cbr>나는 매일 아침 직장에 간다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>동사 + to + 목적지\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>from\u003c/code> — 출발점\u003c/h2>\n\u003cp>\u003ccode>from\u003c/code>은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~에서 / ~로부터\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이다.\u003c/p>\n\u003cblockquote>\n\u003cp>come \u003cstrong>from Busan\u003c/strong>\u003cbr>부산에서 오다\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>walk \u003cstrong>from school\u003c/strong>\u003cbr>학교에서 걸어오다\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I came \u003cstrong>from work\u003c/strong>.\u003cbr>나는 직장에서 왔다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>to\u003c/code>와 \u003ccode>from\u003c/code>\u003c/h2>\n\u003cp>둘은 반대 방향이다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>from A to B\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>A에서 B까지\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I walked \u003cstrong>from home to school\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 집에서 학교까지 걸었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조 자체를 하나의 패턴으로 익혀도 좋다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>from A to B = A에서 B까지\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>into\u003c/code> — 안으로 들어가는 움직임\u003c/h2>\n\u003cp>\u003ccode>into\u003c/code>는 단순히 목적지가 아니라:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>밖 → 안\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>으로 이동한다는 뜻이다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>She went \u003cstrong>into the room\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 방 안으로 들어갔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>처음에는 방 밖에 있었고,\u003cbr>움직인 뒤 방 안에 있게 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. \u003ccode>in\u003c/code>과 \u003ccode>into\u003c/code> 차이\u003c/h2>\n\u003cp>이 차이가 중요하다.\u003c/p>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">\u003ccode>in\u003c/code>\u003c/h3>\n\u003cp>위치\u003c/p>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>in the room\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 방 안에 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>움직임이 없다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">\u003ccode>into\u003c/code>\u003c/h3>\n\u003cp>이동\u003c/p>\n\u003cblockquote>\n\u003cp>She walked \u003cstrong>into the room\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 방 안으로 걸어 들어갔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>밖에서 안으로 움직였다.\u003c/p>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>in = 안에 있다\u003c/strong>\u003cbr>\u003cstrong>into = 안으로 들어가다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. \u003ccode>out of\u003c/code> — 밖으로\u003c/h2>\n\u003cp>\u003ccode>out of\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>안 → 밖\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>으로 이동하는 것을 나타낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>He walked \u003cstrong>out of the room\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그는 방 밖으로 걸어 나갔다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She got \u003cstrong>out of the car\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 차에서 내렸다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. \u003ccode>into\u003c/code>와 \u003ccode>out of\u003c/code>\u003c/h2>\n\u003cp>둘은 서로 반대다.\u003c/p>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">밖 → 안\u003c/h3>\n\u003cblockquote>\n\u003cp>He went \u003cstrong>into the building\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">안 → 밖\u003c/h3>\n\u003cblockquote>\n\u003cp>He came \u003cstrong>out of the building\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">8. \u003ccode>to\u003c/code>와 \u003ccode>into\u003c/code> 차이\u003c/h2>\n\u003cp>이것도 헷갈리기 쉽다.\u003c/p>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">to\u003c/h3>\n\u003cblockquote>\n\u003cp>I went \u003cstrong>to the room\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>방이라는 \u003cstrong>목적지까지 갔다\u003c/strong>는 의미.\u003c/p>\n\u003cp>안으로 들어갔는지는 반드시 알 수 없다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">into\u003c/h3>\n\u003cblockquote>\n\u003cp>I went \u003cstrong>into the room\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>방 \u003cstrong>안으로 들어갔다\u003c/strong>는 의미가 명확하다.\u003c/p>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>to\u003c/code> = 목적지\u003cbr>\u003ccode>into\u003c/code> = 내부로 진입\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">9. \u003ccode>from\u003c/code>과 \u003ccode>out of\u003c/code> 차이\u003c/h2>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">from\u003c/h3>\n\u003cp>출발한 장소를 말한다.\u003c/p>\n\u003cblockquote>\n\u003cp>I came \u003cstrong>from the office\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>사무실에서 왔다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">out of\u003c/h3>\n\u003cp>그 장소의 \u003cstrong>내부에서 외부로 나오는 움직임\u003c/strong>을 강조한다.\u003c/p>\n\u003cblockquote>\n\u003cp>I walked \u003cstrong>out of the office\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>사무실 밖으로 걸어 나왔다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">10. \u003ccode>go home\u003c/code>에는 왜 \u003ccode>to\u003c/code>가 없나?\u003c/h2>\n\u003cp>중요한 예외다.\u003c/p>\n\u003cp>보통:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ go to home\u003cbr>✅ \u003cstrong>go home\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>home\u003c/code>은 \u003ccode>go / come / get\u003c/code> 같은 이동동사 뒤에서 \u003cstrong>부사처럼\u003c/strong> 쓰일 수 있어서 \u003ccode>to\u003c/code>를 쓰지 않는다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>go home\u003cbr>집에 가다\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>come home\u003cbr>집에 오다\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>get home\u003cbr>집에 도착하다\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 \u003ccode>home\u003c/code> 앞에 다른 말이 붙으면 \u003ccode>to\u003c/code>가 나타날 수도 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>go \u003cstrong>to my home\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>문법적으로 가능하지만 일상적으로는 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>go home\u003c/p>\n\u003c/blockquote>\n\u003cp>이 훨씬 자연스럽다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">11. \u003ccode>get into / get out of\u003c/code>\u003c/h2>\n\u003cp>회화에서 아주 자주 함께 쓰인다.\u003c/p>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">get into\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>~안에 들어가다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Get \u003cstrong>into the car\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>차에 타.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">get out of\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>~에서 나오다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Get \u003cstrong>out of the car\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>차에서 내려.\u003c/p>\n\u003c/blockquote>\n\u003cp>특히 자동차에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>get \u003cstrong>in\u003c/strong> the car\u003cbr>get \u003cstrong>into\u003c/strong> the car\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 가능하지만,\u003c/p>\n\u003cblockquote>\n\u003cp>get \u003cstrong>out of\u003c/strong> the car\u003c/p>\n\u003c/blockquote>\n\u003cp>가 기본 표현이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">12. 핵심 구조\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>표현\u003c/th>\n\u003cth>의미\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>go to\u003c/td>\n\u003ctd>~로 가다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>come from\u003c/td>\n\u003ctd>~에서 오다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>go into\u003c/td>\n\u003ctd>~안으로 들어가다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>come out of\u003c/td>\n\u003ctd>~밖으로 나오다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>from A to B\u003c/td>\n\u003ctd>A에서 B까지\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">핵심\u003c/h2>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">위치\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>in the room\u003c/strong>\u003cbr>방 안에\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">내부로 이동\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>into the room\u003c/strong>\u003cbr>방 안으로\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">목적지\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>to the room\u003c/strong>\u003cbr>방으로\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-27\" data-reading-anchor=\"reading-27\">출발점\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>from the room\u003c/strong>\u003cbr>방에서\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-28\" data-reading-anchor=\"reading-28\">밖으로 이동\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>out of the room\u003c/strong>\u003cbr>방 밖으로\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-29\" data-reading-anchor=\"reading-29\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>I go \u003cstrong>to / into\u003c/strong> work every morning.\u003cbr>→ 직장으로 간다.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She walked \u003cstrong>in / into\u003c/strong> the room.\u003cbr>→ 방 안으로 걸어 들어갔다.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>He is \u003cstrong>in / into\u003c/strong> the car.\u003cbr>→ 차 안에 있다.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She came \u003cstrong>from / to\u003c/strong> school.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>He walked \u003cstrong>from / out of\u003c/strong> the building.\u003cbr>→ 건물 밖으로 걸어 나왔다.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I go \u003cstrong>home / to home\u003c/strong> after work.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>30단계 — 목적격 대명사 \u003ccode>me / you / him / her / it / us / them\u003c/code>\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. to — 목적지로","depth":2},{"id":"reading-2","label":"2. from — 출발점","depth":2},{"id":"reading-3","label":"3. to와 from","depth":2},{"id":"reading-4","label":"4. into — 안으로 들어가는 움직임","depth":2},{"id":"reading-5","label":"5. in과 into 차이","depth":2},{"id":"reading-6","label":"in","depth":3},{"id":"reading-7","label":"into","depth":3},{"id":"reading-8","label":"6. out of — 밖으로","depth":2},{"id":"reading-9","label":"7. into와 out of","depth":2},{"id":"reading-10","label":"밖 → 안","depth":3},{"id":"reading-11","label":"안 → 밖","depth":3},{"id":"reading-12","label":"8. to와 into 차이","depth":2},{"id":"reading-13","label":"to","depth":3},{"id":"reading-14","label":"into","depth":3},{"id":"reading-15","label":"9. from과 out of 차이","depth":2},{"id":"reading-16","label":"from","depth":3},{"id":"reading-17","label":"out of","depth":3},{"id":"reading-18","label":"10. go home에는 왜 to가 없나?","depth":2},{"id":"reading-19","label":"11. get into / get out of","depth":2},{"id":"reading-20","label":"get into","depth":3},{"id":"reading-21","label":"get out of","depth":3},{"id":"reading-22","label":"12. 핵심 구조","depth":2},{"id":"reading-23","label":"핵심","depth":2},{"id":"reading-24","label":"위치","depth":3},{"id":"reading-25","label":"내부로 이동","depth":3},{"id":"reading-26","label":"목적지","depth":3},{"id":"reading-27","label":"출발점","depth":3},{"id":"reading-28","label":"밖으로 이동","depth":3},{"id":"reading-29","label":"연습","depth":2}],"origin":"conversation","characters":3343,"aliases":{"structure":"reading-22","examples":"concept","contrast":"reading-5","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-12","topic-9":"reading-15","topic-10":"reading-18","topic-11":"reading-19","topic-12":"reading-22"}},{"id":30,"title":"30단계 — 목적격 대명사 me / you / him / her / it / us / them","html":"\u003ch1 id=\"lesson-title\" data-id=\"30\">30단계 — 목적격 대명사 \u003ccode>me / you / him / her / it / us / them\u003c/code>\u003c/h1>\n\u003cp>앞에서 배운 대명사:\u003c/p>\n\u003cblockquote>\n\u003cp>I / you / he / she / it / we / they\u003c/p>\n\u003c/blockquote>\n\u003cp>이 형태들은 보통 \u003cstrong>주어 자리\u003c/strong>에 쓴다.\u003c/p>\n\u003cp>이번에는 \u003cstrong>목적어 자리\u003c/strong>에서 형태가 어떻게 바뀌는지 배운다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 왜 형태가 바뀌나?\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I\u003c/strong> like her.\u003cbr>나는 그녀를 좋아한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>I\u003c/code>는 행동을 하는 사람이라 \u003cstrong>주어\u003c/strong>다.\u003c/p>\n\u003cp>반대로:\u003c/p>\n\u003cblockquote>\n\u003cp>She likes \u003cstrong>me\u003c/strong>.\u003cbr>그녀는 나를 좋아한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이번에는 내가 행동을 받는 대상이다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>I → me\u003c/p>\n\u003c/blockquote>\n\u003cp>로 바뀐다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 주격과 목적격\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>주격\u003c/th>\n\u003cth>목적격\u003c/th>\n\u003cth>뜻\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>I\u003c/td>\n\u003ctd>me\u003c/td>\n\u003ctd>나 / 나를\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>you\u003c/td>\n\u003ctd>you\u003c/td>\n\u003ctd>너 / 너를\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>he\u003c/td>\n\u003ctd>him\u003c/td>\n\u003ctd>그 / 그를\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>she\u003c/td>\n\u003ctd>her\u003c/td>\n\u003ctd>그녀 / 그녀를\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>it\u003c/td>\n\u003ctd>it\u003c/td>\n\u003ctd>그것 / 그것을\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>we\u003c/td>\n\u003ctd>us\u003c/td>\n\u003ctd>우리 / 우리를\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>they\u003c/td>\n\u003ctd>them\u003c/td>\n\u003ctd>그들 / 그들을\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 주어 자리\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>I\u003c/strong> like coffee.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>She\u003c/strong> knows Tom.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>They\u003c/strong> called me.\u003c/p>\n\u003c/blockquote>\n\u003cp>문장 앞에서 행동의 주체가 되면 주격을 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. 목적어 자리\u003c/h2>\n\u003cblockquote>\n\u003cp>She likes \u003cstrong>me\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>him\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We called \u003cstrong>them\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + 동사 + 목적격\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I love her.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>I = 주어\u003c/li>\n\u003cli>love = 동사\u003c/li>\n\u003cli>her = 목적어\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. \u003ccode>he / him\u003c/code>\u003c/h2>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">주어\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>He\u003c/strong> likes me.\u003cbr>그가 나를 좋아한다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">목적어\u003c/h3>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>him\u003c/strong>.\u003cbr>나는 그를 좋아한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I like he.\u003cbr>✅ I like him.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. \u003ccode>she / her\u003c/code>\u003c/h2>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">주어\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>She\u003c/strong> called me.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">목적어\u003c/h3>\n\u003cblockquote>\n\u003cp>I called \u003cstrong>her\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I called she.\u003cbr>✅ I called her.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">7. \u003ccode>we / us\u003c/code>\u003c/h2>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">주어\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>We\u003c/strong> know him.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">목적어\u003c/h3>\n\u003cblockquote>\n\u003cp>He knows \u003cstrong>us\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>us = 우리를\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">8. \u003ccode>they / them\u003c/code>\u003c/h2>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">주어\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>They\u003c/strong> helped me.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">목적어\u003c/h3>\n\u003cblockquote>\n\u003cp>I helped \u003cstrong>them\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">9. \u003ccode>you / it\u003c/code>은 모양이 같다\u003c/h2>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">you\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>You\u003c/strong> know me.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>you\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 \u003ccode>you\u003c/code>.\u003c/p>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">it\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>It\u003c/strong> is expensive.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I bought \u003cstrong>it\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 \u003ccode>it\u003c/code>.\u003c/p>\n\u003cp>문장에서의 \u003cstrong>자리와 역할\u003c/strong>로 구분한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">10. 전치사 뒤에도 목적격\u003c/h2>\n\u003cp>이것이 아주 중요하다.\u003c/p>\n\u003cp>전치사:\u003c/p>\n\u003cblockquote>\n\u003cp>to / for / with / from / about\u003c/p>\n\u003c/blockquote>\n\u003cp>뒤에 대명사가 오면 \u003cstrong>목적격\u003c/strong>을 쓴다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>with \u003cstrong>me\u003c/strong>\u003cbr>나와 함께\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>for \u003cstrong>her\u003c/strong>\u003cbr>그녀를 위해\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>to \u003cstrong>him\u003c/strong>\u003cbr>그에게\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>from \u003cstrong>them\u003c/strong>\u003cbr>그들로부터\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ with I\u003cbr>✅ with me\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ for she\u003cbr>✅ for her\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">11. 실제 문장\u003c/h2>\n\u003cblockquote>\n\u003cp>Come with \u003cstrong>me\u003c/strong>.\u003cbr>나랑 같이 가.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I bought this for \u003cstrong>her\u003c/strong>.\u003cbr>나는 이것을 그녀를 위해 샀다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He talked to \u003cstrong>us\u003c/strong>.\u003cbr>그는 우리에게 말했다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I got a message from \u003cstrong>him\u003c/strong>.\u003cbr>나는 그에게서 메시지를 받았다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">12. 이름도 목적어가 될 수 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>I called \u003cstrong>Tom\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>Tom\u003c/code>이 목적어다.\u003c/p>\n\u003cp>대명사로 바꾸면:\u003c/p>\n\u003cblockquote>\n\u003cp>I called \u003cstrong>him\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>또:\u003c/p>\n\u003cblockquote>\n\u003cp>I saw \u003cstrong>Mina\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>I saw \u003cstrong>her\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">핵심\u003c/h2>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">행동하는 사람\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>I / he / she / we / they\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">행동을 받는 사람\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>me / him / her / us / them\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>비교:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>She\u003c/strong> likes \u003cstrong>me\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>I\u003c/strong> like \u003cstrong>her\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>전치사 뒤에는 목적격\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>with me\u003cbr>for him\u003cbr>to her\u003cbr>from them\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-26\" data-reading-anchor=\"reading-26\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cstrong>He / Him\u003c/strong> likes coffee.\u003c/li>\n\u003cli>I know \u003cstrong>he / him\u003c/strong>.\u003c/li>\n\u003cli>She called \u003cstrong>I / me\u003c/strong>.\u003c/li>\n\u003cli>We helped \u003cstrong>they / them\u003c/strong>.\u003c/li>\n\u003cli>Come with \u003cstrong>I / me\u003c/strong>.\u003c/li>\n\u003cli>I bought this for \u003cstrong>she / her\u003c/strong>.\u003c/li>\n\u003cli>\u003cstrong>They / Them\u003c/strong> know us.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>31단계 — 소유 표현 \u003ccode>my / your / his / her / our / their\u003c/code>\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 왜 형태가 바뀌나?","depth":2},{"id":"reading-2","label":"2. 주격과 목적격","depth":2},{"id":"reading-3","label":"3. 주어 자리","depth":2},{"id":"reading-4","label":"4. 목적어 자리","depth":2},{"id":"reading-5","label":"5. he / him","depth":2},{"id":"reading-6","label":"주어","depth":3},{"id":"reading-7","label":"목적어","depth":3},{"id":"reading-8","label":"6. she / her","depth":2},{"id":"reading-9","label":"주어","depth":3},{"id":"reading-10","label":"목적어","depth":3},{"id":"reading-11","label":"7. we / us","depth":2},{"id":"reading-12","label":"주어","depth":3},{"id":"reading-13","label":"목적어","depth":3},{"id":"reading-14","label":"8. they / them","depth":2},{"id":"reading-15","label":"주어","depth":3},{"id":"reading-16","label":"목적어","depth":3},{"id":"reading-17","label":"9. you / it은 모양이 같다","depth":2},{"id":"reading-18","label":"you","depth":3},{"id":"reading-19","label":"it","depth":3},{"id":"reading-20","label":"10. 전치사 뒤에도 목적격","depth":2},{"id":"reading-21","label":"11. 실제 문장","depth":2},{"id":"reading-22","label":"12. 이름도 목적어가 될 수 있다","depth":2},{"id":"reading-23","label":"핵심","depth":2},{"id":"reading-24","label":"행동하는 사람","depth":3},{"id":"reading-25","label":"행동을 받는 사람","depth":3},{"id":"reading-26","label":"연습","depth":2}],"origin":"conversation","characters":2593,"aliases":{"structure":"reading-1","examples":"concept","contrast":"concept","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-8","topic-7":"reading-11","topic-8":"reading-14","topic-9":"reading-17","topic-10":"reading-20","topic-11":"reading-21","topic-12":"reading-22"}},{"id":31,"title":"31단계 — 소유 표현 my / your / his / her / our / their","html":"\u003ch1 id=\"lesson-title\" data-id=\"31\">31단계 — 소유 표현 \u003ccode>my / your / his / her / our / their\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>“누구의 것인지”\u003c/strong>를 나타내는 표현이다.\u003c/p>\n\u003cp>핵심 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>소유형용사 + 명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>my car\u003cbr>내 차\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>her bag\u003cbr>그녀의 가방\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 형태\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>주어\u003c/th>\n\u003cth>소유형용사\u003c/th>\n\u003cth>뜻\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>I\u003c/td>\n\u003ctd>my\u003c/td>\n\u003ctd>나의\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>you\u003c/td>\n\u003ctd>your\u003c/td>\n\u003ctd>너의 / 당신의\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>he\u003c/td>\n\u003ctd>his\u003c/td>\n\u003ctd>그의\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>she\u003c/td>\n\u003ctd>her\u003c/td>\n\u003ctd>그녀의\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>it\u003c/td>\n\u003ctd>its\u003c/td>\n\u003ctd>그것의\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>we\u003c/td>\n\u003ctd>our\u003c/td>\n\u003ctd>우리의\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>they\u003c/td>\n\u003ctd>their\u003c/td>\n\u003ctd>그들의\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 명사 앞에 온다\u003c/h2>\n\u003cblockquote>\n\u003cp>my phone\u003cbr>your book\u003cbr>his car\u003cbr>her bag\u003cbr>our house\u003cbr>their children\u003c/p>\n\u003c/blockquote>\n\u003cp>소유형용사는 \u003cstrong>반드시 뒤에 명사가 필요하다.\u003c/strong>\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>This is \u003cstrong>my car\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>her bag\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>I / me / my\u003c/code> 차이\u003c/h2>\n\u003cp>이제 세 가지를 구분해야 한다.\u003c/p>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">I\u003c/h3>\n\u003cp>주어\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I\u003c/strong> like coffee.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">me\u003c/h3>\n\u003cp>목적어\u003c/p>\n\u003cblockquote>\n\u003cp>She likes \u003cstrong>me\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">my\u003c/h3>\n\u003cp>소유\u003c/p>\n\u003cblockquote>\n\u003cp>This is \u003cstrong>my\u003c/strong> coffee.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">4. \u003ccode>she / her / her\u003c/code>\u003c/h2>\n\u003cp>여기가 조금 헷갈릴 수 있다.\u003c/p>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">she\u003c/h3>\n\u003cp>주어\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>She\u003c/strong> is my friend.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">her\u003c/h3>\n\u003cp>목적어\u003c/p>\n\u003cblockquote>\n\u003cp>I called \u003cstrong>her\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">her\u003c/h3>\n\u003cp>소유형용사\u003c/p>\n\u003cblockquote>\n\u003cp>This is \u003cstrong>her\u003c/strong> bag.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>her\u003c/code>는 목적격과 소유형용사 형태가 같다.\u003c/p>\n\u003cp>문장에서 뒤에 명사가 있으면 쉽게 구분된다.\u003c/p>\n\u003cblockquote>\n\u003cp>her bag\u003cbr>→ 소유형용사\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I saw her.\u003cbr>→ 목적격\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">5. \u003ccode>he / him / his\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>He\u003c/strong> is my friend.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>him\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>This is \u003cstrong>his\u003c/strong> car.\u003c/p>\n\u003c/blockquote>\n\u003cp>세 형태가 모두 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">6. \u003ccode>they / them / their\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>They\u003c/strong> live here.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I know \u003cstrong>them\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>This is \u003cstrong>their\u003c/strong> house.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">7. \u003ccode>its\u003c/code>와 \u003ccode>it&#39;s\u003c/code>\u003c/h2>\n\u003cp>이건 반드시 구분해야 한다.\u003c/p>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">its\u003c/h3>\n\u003cblockquote>\n\u003cp>그것의\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>The dog is eating \u003cstrong>its food\u003c/strong>.\u003cbr>그 개는 자기 먹이를 먹고 있다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">it&#39;s\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>it is\u003c/strong>의 축약형\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>It&#39;s cold.\u003c/strong>\u003cbr>= It is cold.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>its = 소유\u003cbr>it&#39;s = it is\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">8. \u003ccode>my\u003c/code> 뒤에 바로 명사\u003c/h2>\n\u003cblockquote>\n\u003cp>my car\u003cbr>my daughter\u003cbr>my phone\u003cbr>my company\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ the my car\u003cbr>✅ my car\u003c/p>\n\u003c/blockquote>\n\u003cp>보통 \u003ccode>my\u003c/code>, \u003ccode>your\u003c/code>, \u003ccode>his\u003c/code> 같은 소유형용사 앞에 \u003ccode>the\u003c/code>를 같이 쓰지 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">9. 지금까지 대명사 체계 정리\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>주격\u003c/th>\n\u003cth>목적격\u003c/th>\n\u003cth>소유형용사\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>I\u003c/td>\n\u003ctd>me\u003c/td>\n\u003ctd>my\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>you\u003c/td>\n\u003ctd>you\u003c/td>\n\u003ctd>your\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>he\u003c/td>\n\u003ctd>him\u003c/td>\n\u003ctd>his\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>she\u003c/td>\n\u003ctd>her\u003c/td>\n\u003ctd>her\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>it\u003c/td>\n\u003ctd>it\u003c/td>\n\u003ctd>its\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>we\u003c/td>\n\u003ctd>us\u003c/td>\n\u003ctd>our\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>they\u003c/td>\n\u003ctd>them\u003c/td>\n\u003ctd>their\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>이 표는 앞으로 계속 중요하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">핵심\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>my / your / his / her / its / our / their + 명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>my book\u003cbr>his phone\u003cbr>her car\u003cbr>our house\u003cbr>their office\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>This is \u003cstrong>I / my\u003c/strong> car.\u003c/li>\n\u003cli>I know \u003cstrong>he / him / his\u003c/strong>.\u003c/li>\n\u003cli>This is \u003cstrong>he / him / his\u003c/strong> phone.\u003c/li>\n\u003cli>She loves \u003cstrong>she / her\u003c/strong> daughter.\u003c/li>\n\u003cli>We like \u003cstrong>our / us\u003c/strong> house.\u003c/li>\n\u003cli>They sold \u003cstrong>their / them\u003c/strong> car.\u003c/li>\n\u003cli>The cat is eating \u003cstrong>it&#39;s / its\u003c/strong> food.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>32단계 — 소유대명사 \u003ccode>mine / yours / his / hers / ours / theirs\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 형태","depth":2},{"id":"reading-2","label":"2. 명사 앞에 온다","depth":2},{"id":"reading-3","label":"3. I / me / my 차이","depth":2},{"id":"reading-4","label":"I","depth":3},{"id":"reading-5","label":"me","depth":3},{"id":"reading-6","label":"my","depth":3},{"id":"reading-7","label":"4. she / her / her","depth":2},{"id":"reading-8","label":"she","depth":3},{"id":"reading-9","label":"her","depth":3},{"id":"reading-10","label":"her","depth":3},{"id":"reading-11","label":"5. he / him / his","depth":2},{"id":"reading-12","label":"6. they / them / their","depth":2},{"id":"reading-13","label":"7. its와 it's","depth":2},{"id":"reading-14","label":"its","depth":3},{"id":"reading-15","label":"it's","depth":3},{"id":"reading-16","label":"8. my 뒤에 바로 명사","depth":2},{"id":"reading-17","label":"9. 지금까지 대명사 체계 정리","depth":2},{"id":"reading-18","label":"핵심","depth":2},{"id":"reading-19","label":"연습","depth":2}],"origin":"conversation","characters":2213,"aliases":{"structure":"reading-1","examples":"concept","contrast":"reading-3","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-7","topic-5":"reading-11","topic-6":"reading-12","topic-7":"reading-13","topic-8":"reading-16","topic-9":"reading-17","topic-10":"reading-18","topic-11":"reading-19","topic-12":"concept"}},{"id":32,"title":"32단계 — 소유대명사 mine / yours / his / hers / ours / theirs","html":"\u003ch1 id=\"lesson-title\" data-id=\"32\">32단계 — 소유대명사 \u003ccode>mine / yours / his / hers / ours / theirs\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>“내 것 / 네 것 / 그의 것”\u003c/strong>처럼 \u003cstrong>명사를 다시 말하지 않고 소유를 표현하는 방법\u003c/strong>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 소유형용사와 소유대명사 차이\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">소유형용사\u003c/h3>\n\u003cp>뒤에 \u003cstrong>명사 필요\u003c/strong>\u003c/p>\n\u003cblockquote>\n\u003cp>my car\u003cbr>내 차\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>her bag\u003cbr>그녀의 가방\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">소유대명사\u003c/h3>\n\u003cp>뒤에 \u003cstrong>명사 없음\u003c/strong>\u003c/p>\n\u003cblockquote>\n\u003cp>mine\u003cbr>내 것\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>hers\u003cbr>그녀의 것\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. 기본 형태\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>소유형용사\u003c/th>\n\u003cth>소유대명사\u003c/th>\n\u003cth>뜻\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>my\u003c/td>\n\u003ctd>mine\u003c/td>\n\u003ctd>내 것\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>your\u003c/td>\n\u003ctd>yours\u003c/td>\n\u003ctd>네 것\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>his\u003c/td>\n\u003ctd>his\u003c/td>\n\u003ctd>그의 것\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>her\u003c/td>\n\u003ctd>hers\u003c/td>\n\u003ctd>그녀의 것\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>our\u003c/td>\n\u003ctd>ours\u003c/td>\n\u003ctd>우리의 것\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>their\u003c/td>\n\u003ctd>theirs\u003c/td>\n\u003ctd>그들의 것\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>\u003ccode>its\u003c/code>는 보통 독립적인 소유대명사 형태로 거의 쓰지 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 비교\u003c/h2>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">my / mine\u003c/h3>\n\u003cblockquote>\n\u003cp>This is \u003cstrong>my car\u003c/strong>.\u003cbr>이것은 내 차다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>This car is \u003cstrong>mine\u003c/strong>.\u003cbr>이 차는 내 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>mine\u003c/code> 뒤에는 \u003ccode>car\u003c/code>를 다시 쓰지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ mine car\u003cbr>✅ my car\u003cbr>✅ This car is mine.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">4. \u003ccode>your / yours\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>Is this \u003cstrong>your bag\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Is this bag \u003cstrong>yours\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다:\u003c/p>\n\u003cblockquote>\n\u003cp>이거 네 가방이야?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. \u003ccode>her / hers\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>This is \u003cstrong>her phone\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>This phone is \u003cstrong>hers\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ hers phone\u003cbr>✅ her phone\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">6. \u003ccode>his\u003c/code>는 형태가 같다\u003c/h2>\n\u003cp>\u003ccode>his\u003c/code>는 특이하게 둘 다 같다.\u003c/p>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">소유형용사\u003c/h3>\n\u003cblockquote>\n\u003cp>his car\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">소유대명사\u003c/h3>\n\u003cblockquote>\n\u003cp>The car is his.\u003c/p>\n\u003c/blockquote>\n\u003cp>문장 위치로 구분한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">7. \u003ccode>our / ours\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>This is \u003cstrong>our house\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>This house is \u003cstrong>ours\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">8. \u003ccode>their / theirs\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>Those are \u003cstrong>their seats\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Those seats are \u003cstrong>theirs\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">9. 왜 소유대명사를 쓰나?\u003c/h2>\n\u003cp>같은 명사를 반복하지 않기 위해서다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>My car is bigger than your car.\u003c/p>\n\u003c/blockquote>\n\u003cp>문법적으로는 맞다.\u003c/p>\n\u003cp>하지만 반복을 피하면:\u003c/p>\n\u003cblockquote>\n\u003cp>My car is bigger than \u003cstrong>yours\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>더 자연스럽다.\u003c/p>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>yours = your car\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">10. 비교급과 연결\u003c/h2>\n\u003cp>이전에 배운 비교급에서 아주 자주 나온다.\u003c/p>\n\u003cblockquote>\n\u003cp>My phone is newer than \u003cstrong>yours\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>yours\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>your phone\u003c/p>\n\u003c/blockquote>\n\u003cp>을 대신한다.\u003c/p>\n\u003cp>또:\u003c/p>\n\u003cblockquote>\n\u003cp>Her house is bigger than \u003cstrong>mine\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>mine\u003c/code>은:\u003c/p>\n\u003cblockquote>\n\u003cp>my house\u003c/p>\n\u003c/blockquote>\n\u003cp>를 대신한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">핵심\u003c/h2>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">명사와 같이\u003c/h3>\n\u003cblockquote>\n\u003cp>my car\u003cbr>your phone\u003cbr>her bag\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">명사를 대신해서\u003c/h3>\n\u003cblockquote>\n\u003cp>mine\u003cbr>yours\u003cbr>hers\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>my + 명사\u003c/strong>\u003cbr>\u003cstrong>mine = my + 명사 전체를 대신\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>This is \u003cstrong>my / mine\u003c/strong> book.\u003c/li>\n\u003cli>This book is \u003cstrong>my / mine\u003c/strong>.\u003c/li>\n\u003cli>Is that \u003cstrong>your / yours\u003c/strong> car?\u003c/li>\n\u003cli>Is that car \u003cstrong>your / yours\u003c/strong>?\u003c/li>\n\u003cli>Her phone is newer than \u003cstrong>my / mine\u003c/strong>.\u003c/li>\n\u003cli>This house is \u003cstrong>our / ours\u003c/strong>.\u003c/li>\n\u003cli>Those seats are \u003cstrong>their / theirs\u003c/strong>.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>33단계 — 지시대명사 \u003ccode>this / that / these / those\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 소유형용사와 소유대명사 차이","depth":2},{"id":"reading-2","label":"소유형용사","depth":3},{"id":"reading-3","label":"소유대명사","depth":3},{"id":"reading-4","label":"2. 기본 형태","depth":2},{"id":"reading-5","label":"3. 비교","depth":2},{"id":"reading-6","label":"my / mine","depth":3},{"id":"reading-7","label":"4. your / yours","depth":2},{"id":"reading-8","label":"5. her / hers","depth":2},{"id":"reading-9","label":"6. his는 형태가 같다","depth":2},{"id":"reading-10","label":"소유형용사","depth":3},{"id":"reading-11","label":"소유대명사","depth":3},{"id":"reading-12","label":"7. our / ours","depth":2},{"id":"reading-13","label":"8. their / theirs","depth":2},{"id":"reading-14","label":"9. 왜 소유대명사를 쓰나?","depth":2},{"id":"reading-15","label":"10. 비교급과 연결","depth":2},{"id":"reading-16","label":"핵심","depth":2},{"id":"reading-17","label":"명사와 같이","depth":3},{"id":"reading-18","label":"명사를 대신해서","depth":3},{"id":"reading-19","label":"연습","depth":2}],"origin":"conversation","characters":2022,"aliases":{"structure":"reading-4","examples":"concept","contrast":"reading-1","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-7","topic-5":"reading-8","topic-6":"reading-9","topic-7":"reading-12","topic-8":"reading-13","topic-9":"reading-14","topic-10":"reading-15","topic-11":"reading-16","topic-12":"reading-19"}},{"id":33,"title":"33단계 — 지시대명사 this / that / these / those","html":"\u003ch1 id=\"lesson-title\" data-id=\"33\">33단계 — 지시대명사 \u003ccode>this / that / these / those\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>가까운 것 / 먼 것\u003c/strong>, 그리고 \u003cstrong>하나 / 여러 개\u003c/strong>를 구분해서 말하는 표현이다.\u003c/p>\n\u003cp>핵심은 이 표 하나다.\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>\u003c/th>\n\u003cth>가까움\u003c/th>\n\u003cth>멂\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>하나\u003c/td>\n\u003ctd>this\u003c/td>\n\u003ctd>that\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>여러 개\u003c/td>\n\u003ctd>these\u003c/td>\n\u003ctd>those\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>this\u003c/code> — 이것\u003c/h2>\n\u003cp>가까이에 있는 \u003cstrong>하나\u003c/strong>를 가리킨다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>This is my phone.\u003c/strong>\u003cbr>이것은 내 휴대폰이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>명사 앞에도 쓸 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>this phone\u003c/strong>\u003cbr>이 휴대폰\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>this = 가까운 것 + 단수\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>that\u003c/code> — 저것 / 그것\u003c/h2>\n\u003cp>조금 떨어져 있는 \u003cstrong>하나\u003c/strong>를 가리킨다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>That is my car.\u003c/strong>\u003cbr>저것은 내 차다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>that car\u003c/strong>\u003cbr>저 차\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>that = 먼 것 + 단수\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>these\u003c/code> — 이것들\u003c/h2>\n\u003cp>가까이 있는 \u003cstrong>여러 개\u003c/strong>를 가리킨다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>These are my shoes.\u003c/strong>\u003cbr>이것들은 내 신발이다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>these shoes\u003c/strong>\u003cbr>이 신발들\u003c/p>\n\u003c/blockquote>\n\u003cp>중요:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ these shoe\u003cbr>✅ these shoes\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>these\u003c/code>는 복수이므로 뒤의 가산명사도 복수형이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. \u003ccode>those\u003c/code> — 저것들\u003c/h2>\n\u003cp>멀리 있는 \u003cstrong>여러 개\u003c/strong>를 가리킨다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Those are my books.\u003c/strong>\u003cbr>저것들은 내 책이다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>those books\u003c/strong>\u003cbr>저 책들\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>those = 먼 것 + 복수\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. \u003ccode>is / are\u003c/code>도 같이 바뀐다\u003c/h2>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">단수\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>This is\u003c/strong> good.\u003cbr>\u003cstrong>That is\u003c/strong> expensive.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">복수\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>These are\u003c/strong> good.\u003cbr>\u003cstrong>Those are\u003c/strong> expensive.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ These is good.\u003cbr>✅ These are good.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. 명사 앞에서도 사용\u003c/h2>\n\u003cp>지금까지 배운 \u003ccode>the\u003c/code>, \u003ccode>my\u003c/code>처럼 명사 앞에 올 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>this book\u003cbr>that book\u003cbr>these books\u003cbr>those books\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>this book\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I don&#39;t like \u003cstrong>those shoes\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. 명사 없이도 사용 가능\u003c/h2>\n\u003cp>대상을 이미 가리키고 있으면 명사를 생략할 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>this\u003c/strong>.\u003cbr>나는 이게 좋아.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I want \u003cstrong>that\u003c/strong>.\u003cbr>나는 저거 원해.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>These\u003c/strong> are mine.\u003cbr>이것들은 내 거야.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Those\u003c/strong> are yours.\u003cbr>저것들은 네 거야.\u003c/p>\n\u003c/blockquote>\n\u003cp>이때는 \u003ccode>this / that / these / those\u003c/code> 자체가 명사를 대신한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. \u003ccode>this one / that one\u003c/code>\u003c/h2>\n\u003cp>회화에서 아주 많이 쓴다.\u003c/p>\n\u003cp>여러 물건 중 하나를 선택하면서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>This one.\u003c/strong>\u003cbr>이거요.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>That one.\u003c/strong>\u003cbr>저거요.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>one\u003c/code>은 앞에서 이미 알고 있는 \u003cstrong>단수명사 하나\u003c/strong>를 대신한다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>Which bag do you want?\u003cbr>어떤 가방 원해?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>This one.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>this one = this bag\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">9. 복수에서는 \u003ccode>ones\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>these ones\u003cbr>those ones\u003c/p>\n\u003c/blockquote>\n\u003cp>도 가능하다.\u003c/p>\n\u003cp>하지만 단순히 가리키는 상황에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>these\u003cbr>those\u003c/p>\n\u003c/blockquote>\n\u003cp>만으로도 충분한 경우가 많다.\u003c/p>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>those\u003c/strong>.\u003cbr>나는 저것들이 좋아.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">핵심\u003c/h2>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">가까움\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>this\u003c/strong> = 이것\u003cbr>\u003cstrong>these\u003c/strong> = 이것들\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">멂\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>that\u003c/strong> = 저것\u003cbr>\u003cstrong>those\u003c/strong> = 저것들\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>this / that → \u003cstrong>단수 + is\u003c/strong>\u003cbr>these / those → \u003cstrong>복수 + are\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cstrong>This / These\u003c/strong> is my phone.\u003c/li>\n\u003cli>\u003cstrong>That / Those\u003c/strong> are my shoes.\u003c/li>\n\u003cli>I like \u003cstrong>this book / these book\u003c/strong>.\u003c/li>\n\u003cli>\u003cstrong>Those cars / That cars\u003c/strong> are expensive.\u003c/li>\n\u003cli>\u003cstrong>These is / These are\u003c/strong> mine.\u003c/li>\n\u003cli>Which one do you want? → \u003cstrong>This one / These one\u003c/strong>\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>34단계 — \u003ccode>there is / there are\u003c/code> : “~이 있다”\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. this — 이것","depth":2},{"id":"reading-2","label":"2. that — 저것 / 그것","depth":2},{"id":"reading-3","label":"3. these — 이것들","depth":2},{"id":"reading-4","label":"4. those — 저것들","depth":2},{"id":"reading-5","label":"5. is / are도 같이 바뀐다","depth":2},{"id":"reading-6","label":"단수","depth":3},{"id":"reading-7","label":"복수","depth":3},{"id":"reading-8","label":"6. 명사 앞에서도 사용","depth":2},{"id":"reading-9","label":"7. 명사 없이도 사용 가능","depth":2},{"id":"reading-10","label":"8. this one / that one","depth":2},{"id":"reading-11","label":"9. 복수에서는 ones","depth":2},{"id":"reading-12","label":"핵심","depth":2},{"id":"reading-13","label":"가까움","depth":3},{"id":"reading-14","label":"멂","depth":3},{"id":"reading-15","label":"연습","depth":2}],"origin":"conversation","characters":2344,"aliases":{"structure":"concept","examples":"concept","contrast":"concept","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-12","topic-11":"reading-15","topic-12":"concept"}},{"id":34,"title":"34단계 — there is / there are","html":"\u003ch1 id=\"lesson-title\" data-id=\"34\">34단계 — \u003ccode>there is / there are\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>“어디에 무엇이 있다”\u003c/strong>를 말하는 구조다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 구조\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">하나가 있을 때\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>There is + 단수명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>There is a book on the table.\u003cbr>탁자 위에 책 한 권이 있다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">여러 개가 있을 때\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>There are + 복수명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>There are two books on the table.\u003cbr>탁자 위에 책 두 권이 있다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. 왜 \u003ccode>There\u003c/code>를 쓰나?\u003c/h2>\n\u003cp>여기서 \u003ccode>there\u003c/code>는 보통 우리가 아는 \u003cstrong>“거기에”\u003c/strong>라는 뜻이 아니다.\u003c/p>\n\u003cp>\u003ccode>There is / There are\u003c/code> 전체가:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~이 있다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 문장 구조다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>There is a dog outside.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻은:\u003c/p>\n\u003cblockquote>\n\u003cp>밖에 개 한 마리가 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이지,\u003c/p>\n\u003cblockquote>\n\u003cp>거기에 개가 있다\u003c/p>\n\u003c/blockquote>\n\u003cp>라고 꼭 해석하는 건 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 단수와 복수\u003c/h2>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">단수\u003c/h3>\n\u003cblockquote>\n\u003cp>There is \u003cstrong>a car\u003c/strong> outside.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">복수\u003c/h3>\n\u003cblockquote>\n\u003cp>There are \u003cstrong>three cars\u003c/strong> outside.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 뒤에 오는 명사가 단수냐 복수냐에 따라:\u003c/p>\n\u003cblockquote>\n\u003cp>is / are\u003c/p>\n\u003c/blockquote>\n\u003cp>가 바뀐다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">4. 불가산명사\u003c/h2>\n\u003cp>불가산명사는 단수 취급하므로 보통 \u003ccode>is\u003c/code>를 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>There is \u003cstrong>some water\u003c/strong> in the bottle.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>병 안에 물이 좀 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>There is \u003cstrong>some information\u003c/strong> here.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">5. 부정문\u003c/h2>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">단수\u003c/h3>\n\u003cblockquote>\n\u003cp>There is not a problem.\u003c/p>\n\u003c/blockquote>\n\u003cp>축약:\u003c/p>\n\u003cblockquote>\n\u003cp>There isn&#39;t a problem.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">복수\u003c/h3>\n\u003cblockquote>\n\u003cp>There are not any problems.\u003c/p>\n\u003c/blockquote>\n\u003cp>축약:\u003c/p>\n\u003cblockquote>\n\u003cp>There aren&#39;t any problems.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">6. \u003ccode>no\u003c/code>도 자주 쓴다\u003c/h2>\n\u003cblockquote>\n\u003cp>There is \u003cstrong>no problem\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>문제가 없다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>There are \u003cstrong>no chairs\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>의자가 하나도 없다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 구조도 매우 자주 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">7. 의문문\u003c/h2>\n\u003cp>be동사를 앞으로 보낸다.\u003c/p>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">단수\u003c/h3>\n\u003cblockquote>\n\u003cp>Is there a bathroom?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>화장실이 있나요?\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">복수\u003c/h3>\n\u003cblockquote>\n\u003cp>Are there any restaurants nearby?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>근처에 식당이 있나요?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">8. \u003ccode>there is\u003c/code>와 \u003ccode>have\u003c/code> 차이\u003c/h2>\n\u003cp>둘 다 한국어로는 “있다”가 될 수 있지만 다르다.\u003c/p>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">have\u003c/h3>\n\u003cblockquote>\n\u003cp>I have a car.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 차를 가지고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003cstrong>소유\u003c/strong>\u003c/p>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">there is\u003c/h3>\n\u003cblockquote>\n\u003cp>There is a car outside.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>밖에 차가 한 대 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003cstrong>존재\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">9. \u003ccode>there is\u003c/code>와 \u003ccode>it is\u003c/code> 차이\u003c/h2>\n\u003cp>이것도 중요하다.\u003c/p>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">There is\u003c/h3>\n\u003cblockquote>\n\u003cp>There is a dog outside.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>밖에 개가 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>새로운 대상의 \u003cstrong>존재를 소개\u003c/strong>\u003c/p>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">It is\u003c/h3>\n\u003cblockquote>\n\u003cp>It is cute.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그것은 귀엽다.\u003c/p>\n\u003c/blockquote>\n\u003cp>이미 알고 있는 대상을 \u003cstrong>설명\u003c/strong>\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>There is a dog outside.\u003cbr>It is very cute.\u003c/p>\n\u003c/blockquote>\n\u003cp>첫 문장에서 개의 존재를 소개하고,\u003cbr>다음 문장에서 \u003ccode>it\u003c/code>으로 그 개를 받는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">핵심\u003c/h2>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">하나 / 불가산\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>There is\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">여러 개\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>There are\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>질문:\u003c/p>\n\u003cblockquote>\n\u003cp>Is there...?\u003cbr>Are there...?\u003c/p>\n\u003c/blockquote>\n\u003cp>부정:\u003c/p>\n\u003cblockquote>\n\u003cp>There isn&#39;t...\u003cbr>There aren&#39;t...\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-25\" data-reading-anchor=\"reading-25\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>There \u003cstrong>is / are\u003c/strong> a book on the table.\u003c/li>\n\u003cli>There \u003cstrong>is / are\u003c/strong> three cars outside.\u003c/li>\n\u003cli>There \u003cstrong>is / are\u003c/strong> some water in the bottle.\u003c/li>\n\u003cli>\u003cstrong>Is there / Are there\u003c/strong> a bathroom here?\u003c/li>\n\u003cli>\u003cstrong>Is there / Are there\u003c/strong> any restaurants nearby?\u003c/li>\n\u003cli>I \u003cstrong>have / there is\u003c/strong> a new phone.\u003cbr>→ 나는 새 휴대폰을 가지고 있다.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>35단계 — \u003ccode>some / any / no\u003c/code>를 \u003ccode>there is/are\u003c/code>와 연결해서 쓰기\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 구조","depth":2},{"id":"reading-2","label":"하나가 있을 때","depth":3},{"id":"reading-3","label":"여러 개가 있을 때","depth":3},{"id":"reading-4","label":"2. 왜 There를 쓰나?","depth":2},{"id":"reading-5","label":"3. 단수와 복수","depth":2},{"id":"reading-6","label":"단수","depth":3},{"id":"reading-7","label":"복수","depth":3},{"id":"reading-8","label":"4. 불가산명사","depth":2},{"id":"reading-9","label":"5. 부정문","depth":2},{"id":"reading-10","label":"단수","depth":3},{"id":"reading-11","label":"복수","depth":3},{"id":"reading-12","label":"6. no도 자주 쓴다","depth":2},{"id":"reading-13","label":"7. 의문문","depth":2},{"id":"reading-14","label":"단수","depth":3},{"id":"reading-15","label":"복수","depth":3},{"id":"reading-16","label":"8. there is와 have 차이","depth":2},{"id":"reading-17","label":"have","depth":3},{"id":"reading-18","label":"there is","depth":3},{"id":"reading-19","label":"9. there is와 it is 차이","depth":2},{"id":"reading-20","label":"There is","depth":3},{"id":"reading-21","label":"It is","depth":3},{"id":"reading-22","label":"핵심","depth":2},{"id":"reading-23","label":"하나 / 불가산","depth":3},{"id":"reading-24","label":"여러 개","depth":3},{"id":"reading-25","label":"연습","depth":2}],"origin":"conversation","characters":2189,"aliases":{"structure":"reading-1","examples":"concept","contrast":"reading-16","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-8","topic-5":"reading-9","topic-6":"reading-12","topic-7":"reading-13","topic-8":"reading-16","topic-9":"reading-19","topic-10":"reading-22","topic-11":"reading-25","topic-12":"concept"}},{"id":35,"title":"35단계 — some / any / no + there is / there are","html":"\u003ch1 id=\"lesson-title\" data-id=\"35\">35단계 — \u003ccode>some / any / no\u003c/code> + \u003ccode>there is / there are\u003c/code>\u003c/h1>\n\u003cp>이번에는 이미 배운 두 개를 연결한다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>there is / there are = ~이 있다\u003c/strong>\u003cbr>\u003cstrong>some / any / no = 수량이나 존재 여부\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>some\u003c/code> — 어느 정도 있다\u003c/h2>\n\u003cp>보통 \u003cstrong>긍정문\u003c/strong>에서 쓴다.\u003c/p>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">가산명사 복수\u003c/h3>\n\u003cblockquote>\n\u003cp>There are \u003cstrong>some books\u003c/strong> on the table.\u003cbr>탁자 위에 책이 몇 권 있다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">불가산명사\u003c/h3>\n\u003cblockquote>\n\u003cp>There is \u003cstrong>some water\u003c/strong> in the bottle.\u003cbr>병에 물이 좀 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>There are + some + 복수명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>There is + some + 불가산명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. \u003ccode>any\u003c/code> — 있는지 없는지 열어둠\u003c/h2>\n\u003cp>보통 \u003cstrong>의문문\u003c/strong>에서 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>Are there \u003cstrong>any books\u003c/strong> here?\u003cbr>여기 책 있어?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Is there \u003cstrong>any water\u003c/strong>?\u003cbr>물 있어?\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>any\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>하나라도 / 조금이라도 있는가?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 느낌이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 부정문에서도 \u003ccode>any\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>There aren&#39;t \u003cstrong>any books\u003c/strong> here.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>여기 책이 하나도 없다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>There isn&#39;t \u003cstrong>any water\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>물이 전혀 없다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>not + any = 하나도 없다 / 전혀 없다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. \u003ccode>no\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>no\u003c/code>를 사용하면 더 간단하게 말할 수 있다.\u003c/p>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">가산명사\u003c/h3>\n\u003cblockquote>\n\u003cp>There are \u003cstrong>no books\u003c/strong> here.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">불가산명사\u003c/h3>\n\u003cblockquote>\n\u003cp>There is \u003cstrong>no water\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻은 각각:\u003c/p>\n\u003cblockquote>\n\u003cp>책이 하나도 없다.\u003cbr>물이 전혀 없다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">5. \u003ccode>not any\u003c/code>와 \u003ccode>no\u003c/code>\u003c/h2>\n\u003cp>의미는 거의 같다.\u003c/p>\n\u003cblockquote>\n\u003cp>There aren&#39;t \u003cstrong>any chairs\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>=\u003c/p>\n\u003cblockquote>\n\u003cp>There are \u003cstrong>no chairs\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다:\u003c/p>\n\u003cblockquote>\n\u003cp>의자가 하나도 없다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">중요한 규칙\u003c/h2>\n\u003cp>\u003ccode>no\u003c/code> 자체가 이미 부정이다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ There aren&#39;t no chairs.\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 \u003ccode>not\u003c/code>과 \u003ccode>no\u003c/code>를 같이 쓰지 않는다.\u003c/p>\n\u003cp>표준 영어에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ There aren&#39;t any chairs.\u003cbr>✅ There are no chairs.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 중 하나를 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">6. 단수 가산명사는?\u003c/h2>\n\u003cp>하나의 존재를 말할 때는 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>There is \u003cstrong>a dog\u003c/strong> outside.\u003c/p>\n\u003c/blockquote>\n\u003cp>부정:\u003c/p>\n\u003cblockquote>\n\u003cp>There isn&#39;t \u003cstrong>a dog\u003c/strong> outside.\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>There is \u003cstrong>no dog\u003c/strong> outside.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">7. 한눈에 비교\u003c/h2>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">긍정\u003c/h3>\n\u003cblockquote>\n\u003cp>There are \u003cstrong>some people\u003c/strong> outside.\u003c/p>\n\u003c/blockquote>\n\u003cp>밖에 사람들이 좀 있다.\u003c/p>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">질문\u003c/h3>\n\u003cblockquote>\n\u003cp>Are there \u003cstrong>any people\u003c/strong> outside?\u003c/p>\n\u003c/blockquote>\n\u003cp>밖에 사람 있어?\u003c/p>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">부정\u003c/h3>\n\u003cblockquote>\n\u003cp>There aren&#39;t \u003cstrong>any people\u003c/strong> outside.\u003c/p>\n\u003c/blockquote>\n\u003cp>밖에 사람이 아무도 없다.\u003c/p>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>There are \u003cstrong>no people\u003c/strong> outside.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">8. 사람에게도 같은 구조\u003c/h2>\n\u003cp>\u003ccode>people\u003c/code>은 복수명사다.\u003c/p>\n\u003cblockquote>\n\u003cp>There are some people in the room.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Are there any people in the room?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>There aren&#39;t any people in the room.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">9. \u003ccode>someone / anyone / no one\u003c/code>으로도 확장된다\u003c/h2>\n\u003cp>같은 원리가 사람을 나타내는 표현에도 이어진다.\u003c/p>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">someone\u003c/h3>\n\u003cblockquote>\n\u003cp>누군가\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>There is \u003cstrong>someone\u003c/strong> outside.\u003cbr>밖에 누군가 있다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">anyone\u003c/h3>\n\u003cblockquote>\n\u003cp>누군가 / 아무도\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Is there \u003cstrong>anyone\u003c/strong> outside?\u003cbr>밖에 누구 있어?\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">no one\u003c/h3>\n\u003cblockquote>\n\u003cp>아무도 없다\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>There is \u003cstrong>no one\u003c/strong> outside.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 구조는 다음 단계에서 자세히 다룬다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">핵심\u003c/h2>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">긍정\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>some\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>There are some books.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">질문\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>any\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Are there any books?\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">부정\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>not + any\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>There aren&#39;t any books.\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>no\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>There are no books.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ not + no\u003cbr>✅ not + any\u003cbr>✅ no\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-25\" data-reading-anchor=\"reading-25\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>There are \u003cstrong>some / any\u003c/strong> books on the table.\u003c/li>\n\u003cli>Are there \u003cstrong>some / any\u003c/strong> chairs here?\u003c/li>\n\u003cli>There isn&#39;t \u003cstrong>some / any\u003c/strong> milk.\u003c/li>\n\u003cli>There is \u003cstrong>no / not no\u003c/strong> water.\u003c/li>\n\u003cli>There aren&#39;t \u003cstrong>any / no\u003c/strong> people here.\u003c/li>\n\u003cli>There are \u003cstrong>no / any\u003c/strong> problems.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>36단계 — \u003ccode>someone / anyone / no one / something / anything / nothing\u003c/code>\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. some — 어느 정도 있다","depth":2},{"id":"reading-2","label":"가산명사 복수","depth":3},{"id":"reading-3","label":"불가산명사","depth":3},{"id":"reading-4","label":"2. any — 있는지 없는지 열어둠","depth":2},{"id":"reading-5","label":"3. 부정문에서도 any","depth":2},{"id":"reading-6","label":"4. no","depth":2},{"id":"reading-7","label":"가산명사","depth":3},{"id":"reading-8","label":"불가산명사","depth":3},{"id":"reading-9","label":"5. not any와 no","depth":2},{"id":"reading-10","label":"중요한 규칙","depth":2},{"id":"reading-11","label":"6. 단수 가산명사는?","depth":2},{"id":"reading-12","label":"7. 한눈에 비교","depth":2},{"id":"reading-13","label":"긍정","depth":3},{"id":"reading-14","label":"질문","depth":3},{"id":"reading-15","label":"부정","depth":3},{"id":"reading-16","label":"8. 사람에게도 같은 구조","depth":2},{"id":"reading-17","label":"9. someone / anyone / no one으로도 확장된다","depth":2},{"id":"reading-18","label":"someone","depth":3},{"id":"reading-19","label":"anyone","depth":3},{"id":"reading-20","label":"no one","depth":3},{"id":"reading-21","label":"핵심","depth":2},{"id":"reading-22","label":"긍정","depth":3},{"id":"reading-23","label":"질문","depth":3},{"id":"reading-24","label":"부정","depth":3},{"id":"reading-25","label":"연습","depth":2}],"origin":"conversation","characters":2613,"aliases":{"structure":"reading-16","examples":"concept","contrast":"reading-12","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-9","topic-6":"reading-10","topic-7":"reading-11","topic-8":"reading-12","topic-9":"reading-16","topic-10":"reading-17","topic-11":"reading-21","topic-12":"reading-25"}},{"id":36,"title":"36단계 — someone / anyone / no one / something / anything / nothing","html":"\u003ch1 id=\"lesson-title\" data-id=\"36\">36단계 — \u003ccode>someone / anyone / no one / something / anything / nothing\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>사람\u003c/strong>과 \u003cstrong>사물\u003c/strong>을 정확히 특정하지 않을 때 쓰는 표현이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 사람을 말할 때\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">someone\u003c/h3>\n\u003cblockquote>\n\u003cp>누군가\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Someone is at the door.\u003c/strong>\u003cbr>누군가 문 앞에 있다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">anyone\u003c/h3>\n\u003cblockquote>\n\u003cp>누군가 / 아무도\u003c/p>\n\u003c/blockquote>\n\u003cp>주로 의문문·부정문에서 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Is anyone there?\u003c/strong>\u003cbr>거기 누구 있어?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I don&#39;t know \u003cstrong>anyone\u003c/strong> here.\u003cbr>나는 여기 아는 사람이 아무도 없다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">no one\u003c/h3>\n\u003cblockquote>\n\u003cp>아무도 ~않다\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>No one is here.\u003c/strong>\u003cbr>아무도 여기 없다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">2. 사물을 말할 때\u003c/h2>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">something\u003c/h3>\n\u003cblockquote>\n\u003cp>무언가\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I need \u003cstrong>something\u003c/strong>.\u003cbr>나는 뭔가 필요하다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">anything\u003c/h3>\n\u003cblockquote>\n\u003cp>무언가 / 아무것도\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Do you need \u003cstrong>anything\u003c/strong>?\u003cbr>뭐 필요한 거 있어?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I don&#39;t need \u003cstrong>anything\u003c/strong>.\u003cbr>아무것도 필요 없어.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">nothing\u003c/h3>\n\u003cblockquote>\n\u003cp>아무것도 ~않다\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I need \u003cstrong>nothing\u003c/strong>.\u003cbr>나는 아무것도 필요하지 않다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">3. 기본 대응\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>긍정\u003c/th>\n\u003cth>의문·부정\u003c/th>\n\u003cth>부정 자체\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>someone\u003c/td>\n\u003ctd>anyone\u003c/td>\n\u003ctd>no one\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>something\u003c/td>\n\u003ctd>anything\u003c/td>\n\u003ctd>nothing\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>기본 패턴은 앞에서 배운:\u003c/p>\n\u003cblockquote>\n\u003cp>some / any / no\u003c/p>\n\u003c/blockquote>\n\u003cp>와 같다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">4. \u003ccode>someone\u003c/code>과 \u003ccode>something\u003c/code>\u003c/h2>\n\u003cp>긍정문에서는 보통 \u003ccode>some-\u003c/code> 계열이 자연스럽다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Someone called me.\u003c/strong>\u003cbr>누군가 나에게 전화했다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I saw \u003cstrong>something\u003c/strong> strange.\u003cbr>나는 이상한 무언가를 봤다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">5. 의문문에서는 \u003ccode>any-\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>Did \u003cstrong>anyone\u003c/strong> call me?\u003cbr>누가 나한테 전화했어?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Did you see \u003cstrong>anything\u003c/strong>?\u003cbr>뭐 봤어?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">6. 부정문에서도 \u003ccode>any-\u003c/code>\u003c/h2>\n\u003cblockquote>\n\u003cp>I didn&#39;t see \u003cstrong>anyone\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>아무도 못 봤어.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I didn&#39;t eat \u003cstrong>anything\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>아무것도 안 먹었어.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 중요한 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>not + anyone = 아무도 ~않다\u003c/strong>\u003cbr>\u003cstrong>not + anything = 아무것도 ~않다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">7. \u003ccode>no one / nothing\u003c/code>은 이미 부정\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>No one came.\u003c/strong>\u003cbr>아무도 오지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Nothing happened.\u003c/strong>\u003cbr>아무 일도 일어나지 않았다.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서 표준 영어에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I didn&#39;t see no one.\u003cbr>✅ I didn&#39;t see anyone.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ I don&#39;t know nothing.\u003cbr>✅ I don&#39;t know anything.\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ I know nothing.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>no one\u003c/code>, \u003ccode>nothing\u003c/code> 자체가 이미 부정이기 때문이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">8. 아주 중요한 문법 — 단수 취급\u003c/h2>\n\u003cp>\u003ccode>someone\u003c/code>, \u003ccode>anyone\u003c/code>, \u003ccode>no one\u003c/code>은 의미상 사람이 누구인지 모르지만 \u003cstrong>문법적으로 단수\u003c/strong>다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>Someone \u003cstrong>is\u003c/strong> outside.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Anyone \u003cstrong>is\u003c/strong> welcome.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>No one \u003cstrong>knows\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>No one know\u003c/code>가 아니라:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ No one \u003cstrong>knows\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>3인칭 단수처럼 취급한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">9. 형용사의 위치가 특이하다\u003c/h2>\n\u003cp>보통 형용사는 명사 앞에 온다고 배웠다.\u003c/p>\n\u003cblockquote>\n\u003cp>a \u003cstrong>good\u003c/strong> book\u003c/p>\n\u003c/blockquote>\n\u003cp>그런데 \u003ccode>something / someone / anything\u003c/code> 같은 단어를 꾸밀 때는 \u003cstrong>형용사가 뒤에 온다.\u003c/strong>\u003c/p>\n\u003cblockquote>\n\u003cp>something \u003cstrong>good\u003c/strong>\u003cbr>좋은 무언가\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>someone \u003cstrong>famous\u003c/strong>\u003cbr>유명한 누군가\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>anything \u003cstrong>interesting\u003c/strong>\u003cbr>흥미로운 무언가\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ good something\u003cbr>✅ something good\u003c/p>\n\u003c/blockquote>\n\u003cp>이건 중요한 고정 구조다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">10. 실제 회화에서 매우 자주 쓰는 표현\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>Something is wrong.\u003c/strong>\u003cbr>뭔가 잘못됐어.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Is something wrong?\u003c/strong>\u003cbr>무슨 일 있어?\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 질문인데 \u003ccode>anything\u003c/code>이 아니라 \u003ccode>something\u003c/code>을 썼다.\u003c/p>\n\u003cp>왜냐하면 말하는 사람이:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>뭔가 문제가 있는 것 같다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>고 어느 정도 예상하고 있기 때문이다.\u003c/p>\n\u003cp>반면 완전히 열린 질문이면:\u003c/p>\n\u003cblockquote>\n\u003cp>Is \u003cstrong>anything\u003c/strong> wrong?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>뭐 문제라도 있어?\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 가능하지만 뉘앙스가 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">핵심\u003c/h2>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">사람\u003c/h3>\n\u003cblockquote>\n\u003cp>someone → 누군가\u003cbr>anyone → 누군가 / 아무도\u003cbr>no one → 아무도 ~않다\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">사물\u003c/h3>\n\u003cblockquote>\n\u003cp>something → 무언가\u003cbr>anything → 무언가 / 아무것도\u003cbr>nothing → 아무것도 ~않다\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>something + 형용사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>something good\u003cbr>something strange\u003cbr>anything interesting\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>\u003cstrong>Someone / Anyone\u003c/strong> called me yesterday.\u003cbr>→ 누군가 전화했다.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>Did \u003cstrong>someone / anyone\u003c/strong> call me?\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I didn&#39;t see \u003cstrong>anyone / no one\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003cstrong>No one know / No one knows\u003c/strong> the answer.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I want \u003cstrong>something cold / cold something\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I didn&#39;t eat \u003cstrong>anything / nothing\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>37단계 — \u003ccode>who / what / where / when / why / how\u003c/code> 의문사\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 사람을 말할 때","depth":2},{"id":"reading-2","label":"someone","depth":3},{"id":"reading-3","label":"anyone","depth":3},{"id":"reading-4","label":"no one","depth":3},{"id":"reading-5","label":"2. 사물을 말할 때","depth":2},{"id":"reading-6","label":"something","depth":3},{"id":"reading-7","label":"anything","depth":3},{"id":"reading-8","label":"nothing","depth":3},{"id":"reading-9","label":"3. 기본 대응","depth":2},{"id":"reading-10","label":"4. someone과 something","depth":2},{"id":"reading-11","label":"5. 의문문에서는 any-","depth":2},{"id":"reading-12","label":"6. 부정문에서도 any-","depth":2},{"id":"reading-13","label":"7. no one / nothing은 이미 부정","depth":2},{"id":"reading-14","label":"8. 아주 중요한 문법 — 단수 취급","depth":2},{"id":"reading-15","label":"9. 형용사의 위치가 특이하다","depth":2},{"id":"reading-16","label":"10. 실제 회화에서 매우 자주 쓰는 표현","depth":2},{"id":"reading-17","label":"핵심","depth":2},{"id":"reading-18","label":"사람","depth":3},{"id":"reading-19","label":"사물","depth":3},{"id":"reading-20","label":"연습","depth":2}],"origin":"conversation","characters":3039,"aliases":{"structure":"concept","examples":"concept","contrast":"concept","topic-1":"reading-1","topic-2":"reading-5","topic-3":"reading-9","topic-4":"reading-10","topic-5":"reading-11","topic-6":"reading-12","topic-7":"reading-13","topic-8":"reading-14","topic-9":"reading-15","topic-10":"reading-16","topic-11":"reading-17","topic-12":"reading-20"}},{"id":37,"title":"37단계 — 의문사 who / what / where / when / why / how","html":"\u003ch1 id=\"lesson-title\" data-id=\"37\">37단계 — 의문사 \u003ccode>who / what / where / when / why / how\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>예/아니오가 아니라 구체적인 정보를 묻는 질문\u003c/strong>을 만든다.\u003c/p>\n\u003cp>핵심 의문사는:\u003c/p>\n\u003cul>\n\u003cli>who = 누구\u003c/li>\n\u003cli>what = 무엇\u003c/li>\n\u003cli>where = 어디\u003c/li>\n\u003cli>when = 언제\u003c/li>\n\u003cli>why = 왜\u003c/li>\n\u003cli>how = 어떻게\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 구조\u003c/h2>\n\u003cp>일반적인 의문사 질문은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>의문사 + 의문문 구조\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>즉, 앞에서 배운 질문 앞에 의문사를 붙인다.\u003c/p>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">일반동사\u003c/h3>\n\u003cblockquote>\n\u003cp>Where \u003cstrong>do you work\u003c/strong>?\u003cbr>어디에서 일해?\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Where + do + 주어 + 동사원형?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">be동사\u003c/h3>\n\u003cblockquote>\n\u003cp>Where \u003cstrong>are you\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Where + be동사 + 주어?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">조동사\u003c/h3>\n\u003cblockquote>\n\u003cp>When \u003cstrong>can you come\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>When + 조동사 + 주어 + 동사원형?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">2. \u003ccode>what\u003c/code> — 무엇\u003c/h2>\n\u003cblockquote>\n\u003cp>What do you want?\u003cbr>뭐 원해?\u003c/p>\n\u003c/blockquote>\n\u003cp>구조를 보면:\u003c/p>\n\u003cblockquote>\n\u003cp>What / do / you / want?\u003c/p>\n\u003c/blockquote>\n\u003cp>이미 배운:\u003c/p>\n\u003cblockquote>\n\u003cp>Do you want it?\u003c/p>\n\u003c/blockquote>\n\u003cp>앞에 \u003ccode>what\u003c/code>이 붙고, \u003ccode>it\u003c/code> 자리를 대신한 것이다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">예\u003c/h3>\n\u003cblockquote>\n\u003cp>What do you eat for breakfast?\u003cbr>아침으로 뭐 먹어?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>What does she want?\u003cbr>그녀는 무엇을 원해?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>does\u003c/code>가 있으므로:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ What does she \u003cstrong>want\u003c/strong>?\u003cbr>❌ What does she \u003cstrong>wants\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">3. \u003ccode>where\u003c/code> — 어디\u003c/h2>\n\u003cblockquote>\n\u003cp>Where do you live?\u003cbr>어디 살아?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Where does she work?\u003cbr>그녀는 어디에서 일해?\u003c/p>\n\u003c/blockquote>\n\u003cp>be동사라면:\u003c/p>\n\u003cblockquote>\n\u003cp>Where is she?\u003cbr>그녀 어디 있어?\u003c/p>\n\u003c/blockquote>\n\u003cp>중요한 차이:\u003c/p>\n\u003cblockquote>\n\u003cp>Where \u003cstrong>does she work\u003c/strong>?\u003cbr>일반동사 \u003ccode>work\u003c/code>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Where \u003cstrong>is she\u003c/strong>?\u003cbr>be동사\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">4. \u003ccode>when\u003c/code> — 언제\u003c/h2>\n\u003cblockquote>\n\u003cp>When do you work?\u003cbr>언제 일해?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>When does school start?\u003cbr>학교는 언제 시작해?\u003c/p>\n\u003c/blockquote>\n\u003cp>과거라면:\u003c/p>\n\u003cblockquote>\n\u003cp>When did you arrive?\u003cbr>언제 도착했어?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>did\u003c/code>가 있으므로:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ When did you \u003cstrong>arrive\u003c/strong>?\u003cbr>❌ When did you \u003cstrong>arrived\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">5. \u003ccode>why\u003c/code> — 왜\u003c/h2>\n\u003cblockquote>\n\u003cp>Why are you tired?\u003cbr>왜 피곤해?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Why do you like this?\u003cbr>왜 이게 좋아?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Why did she leave?\u003cbr>그녀는 왜 떠났어?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>why\u003c/code> 자체 때문에 문장 구조가 바뀌는 게 아니다.\u003c/p>\n\u003cp>뒤에 오는 문장이:\u003c/p>\n\u003cblockquote>\n\u003cp>be동사인지\u003cbr>일반동사인지\u003cbr>조동사인지\u003c/p>\n\u003c/blockquote>\n\u003cp>판단하면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">6. \u003ccode>how\u003c/code> — 어떻게\u003c/h2>\n\u003cblockquote>\n\u003cp>How do you go to work?\u003cbr>어떻게 출근해?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>How did you do that?\u003cbr>그거 어떻게 했어?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>How can I use this?\u003cbr>이거 어떻게 사용할 수 있어?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">7. \u003ccode>who\u003c/code> — 누구\u003c/h2>\n\u003cp>기본적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>Who did you call?\u003cbr>누구한테 전화했어?\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cul>\n\u003cli>who = 목적어\u003c/li>\n\u003cli>did = 과거 질문\u003c/li>\n\u003cli>you = 주어\u003c/li>\n\u003cli>call = 동사원형\u003c/li>\n\u003c/ul>\n\u003cp>원래 평서문을 보면:\u003c/p>\n\u003cblockquote>\n\u003cp>You called \u003cstrong>Tom\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>Tom을 모르면:\u003c/p>\n\u003cblockquote>\n\u003cp>Who did you call?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">8. \u003ccode>who\u003c/code>에는 중요한 예외가 있다\u003c/h2>\n\u003cp>\u003ccode>who\u003c/code> 자체가 \u003cstrong>주어\u003c/strong>일 때는 \u003ccode>do / does / did\u003c/code>를 쓰지 않는다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Who called you?\u003c/strong>\u003cbr>누가 너한테 전화했어?\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>who\u003c/code>가 전화한 사람, 즉 \u003cstrong>주어\u003c/strong>다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Who did call you?\u003cbr>✅ Who called you?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">비교하면 확실하다\u003c/h2>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">누가 너에게 전화했어?\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>Who called you?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>who\u003c/code> = 주어\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">너는 누구에게 전화했어?\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>Who did you call?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>you\u003c/code> = 주어\u003cbr>\u003ccode>who\u003c/code> = 목적어\u003c/p>\n\u003cp>둘은 완전히 다른 구조다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">9. \u003ccode>what\u003c/code>도 주어가 될 수 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>What happened?\u003c/strong>\u003cbr>무슨 일이 일어났어?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>what\u003c/code> 자체가 일어난 사건의 주어다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ What did happen?\u003cbr>✅ What happened?\u003c/p>\n\u003c/blockquote>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>What did you buy?\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는:\u003c/p>\n\u003cblockquote>\n\u003cp>you = 주어\u003cbr>what = 목적어\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서 \u003ccode>did\u003c/code>가 필요하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">10. 전체 구조\u003c/h2>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">be동사\u003c/h3>\n\u003cblockquote>\n\u003cp>Where \u003cstrong>are you\u003c/strong>?\u003cbr>Why \u003cstrong>is she\u003c/strong> angry?\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">일반동사 현재\u003c/h3>\n\u003cblockquote>\n\u003cp>What \u003cstrong>do you want\u003c/strong>?\u003cbr>Where \u003cstrong>does he live\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">일반동사 과거\u003c/h3>\n\u003cblockquote>\n\u003cp>Why \u003cstrong>did she leave\u003c/strong>?\u003cbr>When \u003cstrong>did you arrive\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">조동사\u003c/h3>\n\u003cblockquote>\n\u003cp>When \u003cstrong>can you come\u003c/strong>?\u003cbr>What \u003cstrong>should I do\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">핵심\u003c/h2>\n\u003cp>보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>의문사 + 원래 의문문 구조\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>Where + do you live?\u003cbr>Why + is she angry?\u003cbr>When + can you come?\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 의문사 자체가 \u003cstrong>주어\u003c/strong>라면:\u003c/p>\n\u003cblockquote>\n\u003cp>Who called you?\u003cbr>What happened?\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 \u003ccode>do / does / did\u003c/code>를 쓰지 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cstrong>Where do you live? / Where you live?\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>Why is she tired? / Why does she tired?\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>What does he want? / What does he wants?\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>When did you arrive? / When did you arrived?\u003c/strong>\u003c/li>\n\u003cli>“누가 너에게 전화했어?”\u003cbr>→ \u003cstrong>Who called you? / Who did you call?\u003c/strong>\u003c/li>\n\u003cli>“너는 누구에게 전화했어?”\u003cbr>→ \u003cstrong>Who called you? / Who did you call?\u003c/strong>\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>38단계 — \u003ccode>how much / how many / how long / how often\u003c/code>\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 구조","depth":2},{"id":"reading-2","label":"일반동사","depth":3},{"id":"reading-3","label":"be동사","depth":3},{"id":"reading-4","label":"조동사","depth":3},{"id":"reading-5","label":"2. what — 무엇","depth":2},{"id":"reading-6","label":"예","depth":3},{"id":"reading-7","label":"3. where — 어디","depth":2},{"id":"reading-8","label":"4. when — 언제","depth":2},{"id":"reading-9","label":"5. why — 왜","depth":2},{"id":"reading-10","label":"6. how — 어떻게","depth":2},{"id":"reading-11","label":"7. who — 누구","depth":2},{"id":"reading-12","label":"8. who에는 중요한 예외가 있다","depth":2},{"id":"reading-13","label":"비교하면 확실하다","depth":2},{"id":"reading-14","label":"누가 너에게 전화했어?","depth":3},{"id":"reading-15","label":"너는 누구에게 전화했어?","depth":3},{"id":"reading-16","label":"9. what도 주어가 될 수 있다","depth":2},{"id":"reading-17","label":"10. 전체 구조","depth":2},{"id":"reading-18","label":"be동사","depth":3},{"id":"reading-19","label":"일반동사 현재","depth":3},{"id":"reading-20","label":"일반동사 과거","depth":3},{"id":"reading-21","label":"조동사","depth":3},{"id":"reading-22","label":"핵심","depth":2},{"id":"reading-23","label":"연습","depth":2}],"origin":"conversation","characters":3278,"aliases":{"structure":"reading-1","examples":"reading-6","contrast":"reading-13","topic-1":"reading-1","topic-2":"reading-5","topic-3":"reading-7","topic-4":"reading-8","topic-5":"reading-9","topic-6":"reading-10","topic-7":"reading-11","topic-8":"reading-12","topic-9":"reading-13","topic-10":"reading-16","topic-11":"reading-17","topic-12":"reading-22"}},{"id":38,"title":"38단계 — how much / how many / how long / how often","html":"\u003ch1 id=\"lesson-title\" data-id=\"38\">38단계 — \u003ccode>how much / how many / how long / how often\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003ccode>how\u003c/code>가 다른 단어와 결합해서 \u003cstrong>수량·기간·빈도\u003c/strong>를 묻는 구조를 배운다.\u003c/p>\n\u003cp>핵심은 이 네 가지다.\u003c/p>\n\u003cul>\n\u003cli>\u003cstrong>how much\u003c/strong> = 얼마나 많은 / 얼마\u003c/li>\n\u003cli>\u003cstrong>how many\u003c/strong> = 몇 개\u003c/li>\n\u003cli>\u003cstrong>how long\u003c/strong> = 얼마나 오래\u003c/li>\n\u003cli>\u003cstrong>how often\u003c/strong> = 얼마나 자주\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>how many\u003c/code> — 몇 개\u003c/h2>\n\u003cp>\u003cstrong>셀 수 있는 명사\u003c/strong>의 개수를 묻는다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>How many + 복수명사 + 의문문?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>How many books do you have?\u003c/strong>\u003cbr>책 몇 권 가지고 있어?\u003c/p>\n\u003c/blockquote>\n\u003cp>중요:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ How many \u003cstrong>books\u003c/strong>\u003cbr>❌ How many \u003cstrong>book\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>many\u003c/code> 뒤에는 \u003cstrong>가산명사 복수형\u003c/strong>이 온다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">예문\u003c/h3>\n\u003cblockquote>\n\u003cp>How many children do you have?\u003cbr>아이가 몇 명 있어?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>How many cars does he have?\u003cbr>그는 차가 몇 대 있어?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>How many people are there?\u003cbr>사람이 몇 명 있어?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">2. 문장 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>How many books do you have?\u003c/p>\n\u003c/blockquote>\n\u003cp>분석하면:\u003c/p>\n\u003cul>\n\u003cli>How many = 몇 개의\u003c/li>\n\u003cli>books = 명사\u003c/li>\n\u003cli>do = 의문문을 만드는 조동사\u003c/li>\n\u003cli>you = 주어\u003c/li>\n\u003cli>have = 동사원형\u003c/li>\n\u003c/ul>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>How many + 명사 + do/does + 주어 + 동사원형?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">3. \u003ccode>how much\u003c/code> — 얼마나 많은\u003c/h2>\n\u003cp>\u003ccode>how much\u003c/code>는 \u003cstrong>셀 수 없는 명사\u003c/strong>의 양을 묻는다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>How much water do you drink?\u003c/strong>\u003cbr>물을 얼마나 마셔?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>How much money do you have?\u003c/strong>\u003cbr>돈이 얼마나 있어?\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>How much + 불가산명사 + 의문문?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">4. \u003ccode>how many\u003c/code>와 \u003ccode>how much\u003c/code>\u003c/h2>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">가산명사\u003c/h3>\n\u003cblockquote>\n\u003cp>books\u003cbr>apples\u003cbr>cars\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>How many books?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">불가산명사\u003c/h3>\n\u003cblockquote>\n\u003cp>water\u003cbr>money\u003cbr>information\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>How much water?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. \u003ccode>how much\u003c/code>는 가격도 묻는다\u003c/h2>\n\u003cp>아주 중요하다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>How much is this?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이거 얼마예요?\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 뒤에 \u003ccode>money\u003c/code>가 없어도:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>가격이 얼마인가?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이 된다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">복수 물건\u003c/h3>\n\u003cblockquote>\n\u003cp>How much are these?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이것들은 얼마예요?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>this → is\u003c/code>\u003cbr>\u003ccode>these → are\u003c/code>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">6. \u003ccode>how long\u003c/code> — 얼마나 오래\u003c/h2>\n\u003cp>시간의 \u003cstrong>길이·기간\u003c/strong>을 묻는다.\u003c/p>\n\u003cblockquote>\n\u003cp>How long do you work every day?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>매일 얼마나 오래 일해?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>How long did you stay there?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>거기 얼마나 오래 있었어?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">답변\u003c/h2>\n\u003cblockquote>\n\u003cp>For two hours.\u003cbr>두 시간 동안.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>For three days.\u003cbr>3일 동안.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>how long\u003c/code>은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>얼마 동안?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이라고 생각하면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">7. \u003ccode>how long\u003c/code>은 길이도 묻는다\u003c/h2>\n\u003cp>\u003ccode>long\u003c/code> 자체가 \u003cstrong>긴\u003c/strong>이라는 뜻도 있기 때문에 물리적인 길이도 물을 수 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>How long is the bridge?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그 다리는 얼마나 길어?\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 문맥에 따라:\u003c/p>\n\u003cblockquote>\n\u003cp>시간의 길이\u003cbr>물체의 길이\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 가능하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">8. \u003ccode>how often\u003c/code> — 얼마나 자주\u003c/h2>\n\u003cp>행동의 \u003cstrong>빈도\u003c/strong>를 묻는다.\u003c/p>\n\u003cblockquote>\n\u003cp>How often do you exercise?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>얼마나 자주 운동해?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>How often does she call you?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 얼마나 자주 전화해?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">답변\u003c/h2>\n\u003cblockquote>\n\u003cp>Every day.\u003cbr>매일.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Twice a week.\u003cbr>일주일에 두 번.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Sometimes.\u003cbr>가끔.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Once a month.\u003cbr>한 달에 한 번.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">9. 빈도 표현\u003c/h2>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">once\u003c/h3>\n\u003cblockquote>\n\u003cp>한 번\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">twice\u003c/h3>\n\u003cblockquote>\n\u003cp>두 번\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">three times\u003c/h3>\n\u003cblockquote>\n\u003cp>세 번\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>once a week\u003cbr>일주일에 한 번\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>twice a month\u003cbr>한 달에 두 번\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>three times a year\u003cbr>일 년에 세 번\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">10. 네 표현 비교\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>표현\u003c/th>\n\u003cth>묻는 것\u003c/th>\n\u003cth>예\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>how many\u003c/td>\n\u003ctd>개수\u003c/td>\n\u003ctd>How many books?\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>how much\u003c/td>\n\u003ctd>양 / 가격\u003c/td>\n\u003ctd>How much water?\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>how long\u003c/td>\n\u003ctd>기간 / 길이\u003c/td>\n\u003ctd>How long did you stay?\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>how often\u003c/td>\n\u003ctd>빈도\u003c/td>\n\u003ctd>How often do you exercise?\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">11. 자주 틀리는 구조\u003c/h2>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">몇 개의 사과가 필요해?\u003c/h3>\n\u003cblockquote>\n\u003cp>✅ How many apples do you need?\u003cbr>❌ How much apples do you need?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>apple\u003c/code>은 가산명사이므로 \u003ccode>many\u003c/code>.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">물이 얼마나 필요해?\u003c/h3>\n\u003cblockquote>\n\u003cp>✅ How much water do you need?\u003cbr>❌ How many water do you need?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>water\u003c/code>는 불가산명사이므로 \u003ccode>much\u003c/code>.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">얼마나 자주 영어 공부해?\u003c/h3>\n\u003cblockquote>\n\u003cp>✅ How often do you study English?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>How many\u003c/code>가 아니다.\u003c/p>\n\u003cp>여기서는 개수를 묻는 것이 아니라 \u003cstrong>빈도\u003c/strong>를 묻는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-24\" data-reading-anchor=\"reading-24\">핵심\u003c/h2>\n\u003ch3 id=\"reading-25\" data-reading-anchor=\"reading-25\">개수\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>How many + 복수명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-26\" data-reading-anchor=\"reading-26\">양\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>How much + 불가산명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-27\" data-reading-anchor=\"reading-27\">기간\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>How long\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-28\" data-reading-anchor=\"reading-28\">빈도\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>How often\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-29\" data-reading-anchor=\"reading-29\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cstrong>How many / How much\u003c/strong> books do you have?\u003c/li>\n\u003cli>\u003cstrong>How many / How much\u003c/strong> water do you drink?\u003c/li>\n\u003cli>\u003cstrong>How long / How often\u003c/strong> do you exercise?\u003cbr>→ 얼마나 자주?\u003c/li>\n\u003cli>\u003cstrong>How long / How often\u003c/strong> did you stay in Japan?\u003cbr>→ 얼마나 오래?\u003c/li>\n\u003cli>\u003cstrong>How much / How many\u003c/strong> is this?\u003c/li>\n\u003cli>How many \u003cstrong>car / cars\u003c/strong> does she have?\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>39단계 — \u003ccode>to부정사\u003c/code>: \u003ccode>to + 동사원형\u003c/code>의 기본 구조와 의미\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. how many — 몇 개","depth":2},{"id":"reading-2","label":"예문","depth":3},{"id":"reading-3","label":"2. 문장 구조","depth":2},{"id":"reading-4","label":"3. how much — 얼마나 많은","depth":2},{"id":"reading-5","label":"4. how many와 how much","depth":2},{"id":"reading-6","label":"가산명사","depth":3},{"id":"reading-7","label":"불가산명사","depth":3},{"id":"reading-8","label":"5. how much는 가격도 묻는다","depth":2},{"id":"reading-9","label":"복수 물건","depth":3},{"id":"reading-10","label":"6. how long — 얼마나 오래","depth":2},{"id":"reading-11","label":"답변","depth":2},{"id":"reading-12","label":"7. how long은 길이도 묻는다","depth":2},{"id":"reading-13","label":"8. how often — 얼마나 자주","depth":2},{"id":"reading-14","label":"답변","depth":2},{"id":"reading-15","label":"9. 빈도 표현","depth":2},{"id":"reading-16","label":"once","depth":3},{"id":"reading-17","label":"twice","depth":3},{"id":"reading-18","label":"three times","depth":3},{"id":"reading-19","label":"10. 네 표현 비교","depth":2},{"id":"reading-20","label":"11. 자주 틀리는 구조","depth":2},{"id":"reading-21","label":"몇 개의 사과가 필요해?","depth":3},{"id":"reading-22","label":"물이 얼마나 필요해?","depth":3},{"id":"reading-23","label":"얼마나 자주 영어 공부해?","depth":3},{"id":"reading-24","label":"핵심","depth":2},{"id":"reading-25","label":"개수","depth":3},{"id":"reading-26","label":"양","depth":3},{"id":"reading-27","label":"기간","depth":3},{"id":"reading-28","label":"빈도","depth":3},{"id":"reading-29","label":"연습","depth":2}],"origin":"conversation","characters":3336,"aliases":{"structure":"reading-3","examples":"reading-2","contrast":"reading-19","topic-1":"reading-1","topic-2":"reading-3","topic-3":"reading-4","topic-4":"reading-5","topic-5":"reading-8","topic-6":"reading-10","topic-7":"reading-11","topic-8":"reading-12","topic-9":"reading-13","topic-10":"reading-14","topic-11":"reading-15","topic-12":"reading-19"}},{"id":39,"title":"39단계 — to부정사 to + 동사원형","html":"\u003ch1 id=\"lesson-title\" data-id=\"39\">39단계 — to부정사 \u003ccode>to + 동사원형\u003c/code>\u003c/h1>\n\u003cp>이번 단계에서는 to부정사의 \u003cstrong>형태와 가장 기본적인 쓰임\u003c/strong>만 잡는다.\u003c/p>\n\u003cp>핵심 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>to eat\u003cbr>먹는 것 / 먹기 / 먹으려고\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>to go\u003cbr>가는 것 / 가기 / 가려고\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>to study\u003cbr>공부하는 것 / 공부하기 / 공부하려고\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>to\u003c/code>만 보고 뜻을 정하는 게 아니라, \u003cstrong>문장 안에서 역할\u003c/strong>을 봐야 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 왜 \u003ccode>to + 동사\u003c/code>를 쓰나?\u003c/h2>\n\u003cp>영어에서는 동사를 그대로 연속해서 쓰지 못하는 경우가 많다.\u003c/p>\n\u003cp>예를 들어:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 집에 가고 싶다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>want\u003c/code>도 동사이고 \u003ccode>go\u003c/code>도 동사다.\u003c/p>\n\u003cp>그렇다고:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I want go home.\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 일반동사 두 개를 바로 붙이지 않는다.\u003c/p>\n\u003cp>\u003ccode>go\u003c/code>를 \u003ccode>to go\u003c/code> 형태로 바꾼다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ I want \u003cstrong>to go\u003c/strong> home.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + 동사 + to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I want \u003cstrong>to eat\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She wants \u003cstrong>to sleep\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We need \u003cstrong>to leave\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>앞의 동사가 문장의 중심 동사이고,\u003cbr>\u003ccode>to + 동사원형\u003c/code>이 그 뒤에서 내용을 보충한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>want to\u003c/code> — ~하고 싶다\u003c/h2>\n\u003cp>가장 먼저 하나의 묶음으로 익힌다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>want to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">예\u003c/h3>\n\u003cblockquote>\n\u003cp>I want to eat.\u003cbr>나는 먹고 싶다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I want to go home.\u003cbr>나는 집에 가고 싶다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She wants to travel.\u003cbr>그녀는 여행하고 싶어 한다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">문장 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>She wants to travel.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>She = 주어\u003c/li>\n\u003cli>wants = 중심동사\u003c/li>\n\u003cli>to travel = 여행하기를\u003c/li>\n\u003c/ul>\n\u003cp>주어가 \u003ccode>she\u003c/code>이므로:\u003c/p>\n\u003cblockquote>\n\u003cp>want → \u003cstrong>wants\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 \u003ccode>to\u003c/code> 뒤의 동사는 항상 원형이다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ She wants to \u003cstrong>go\u003c/strong>.\u003cbr>❌ She wants to \u003cstrong>goes\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. \u003ccode>need to\u003c/code> — ~할 필요가 있다 / ~해야 한다\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>need to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I need to work.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 일해야 한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You need to rest.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>너는 좀 쉬어야 한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She needs to study.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>그녀는 공부해야 한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>역시:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ She needs to \u003cstrong>study\u003c/strong>.\u003cbr>❌ She needs to \u003cstrong>studies\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. 자주 쓰이는 \u003ccode>동사 + to부정사\u003c/code>\u003c/h2>\n\u003cp>지금은 아래 표현들을 \u003cstrong>통째로 익히는 것\u003c/strong>이 좋다.\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>표현\u003c/th>\n\u003cth>의미\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>want to\u003c/td>\n\u003ctd>~하고 싶다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>need to\u003c/td>\n\u003ctd>~할 필요가 있다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>plan to\u003c/td>\n\u003ctd>~할 계획이다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>hope to\u003c/td>\n\u003ctd>~하기를 바라다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>decide to\u003c/td>\n\u003ctd>~하기로 결정하다\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>try to\u003c/td>\n\u003ctd>~하려고 노력하다\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I plan \u003cstrong>to travel\u003c/strong> next year.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We decided \u003cstrong>to leave\u003c/strong> early.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;ll try \u003cstrong>to finish\u003c/strong> this today.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. 부정형\u003c/h2>\n\u003cp>\u003ccode>to부정사 자체\u003c/code>를 부정하려면:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>not to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I decided \u003cstrong>not to go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 가지 않기로 결정했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>decide + not to go\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003cp>하지만 중심동사를 부정할 수도 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>don&#39;t want to go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 가고 싶지 않다.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘은 구조가 다르다.\u003c/p>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">I don&#39;t want to go.\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>가고 싶지 않다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">I decided not to go.\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>가지 않기로 결정했다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">7. \u003ccode>to\u003c/code> 뒤에는 무조건 동사원형\u003c/h2>\n\u003cp>이 규칙이 매우 중요하다.\u003c/p>\n\u003cblockquote>\n\u003cp>to go ✅\u003cbr>to eat ✅\u003cbr>to study ✅\u003cbr>to work ✅\u003c/p>\n\u003c/blockquote>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ to goes\u003cbr>❌ to ate\u003cbr>❌ to studying\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">8. 그런데 모든 동사 뒤에 \u003ccode>to\u003c/code>를 쓰는 것은 아니다\u003c/h2>\n\u003cp>여기가 앞으로 중요해진다.\u003c/p>\n\u003cp>예를 들어 조동사 뒤에는:\u003c/p>\n\u003cblockquote>\n\u003cp>can \u003cstrong>go\u003c/strong>\u003cbr>should \u003cstrong>go\u003c/strong>\u003cbr>must \u003cstrong>go\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이지:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ can to go\u003cbr>❌ should to go\u003cbr>❌ must to go\u003c/p>\n\u003c/blockquote>\n\u003cp>가 아니다.\u003c/p>\n\u003cp>왜냐하면 이미 배웠듯:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>조동사 + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이 하나의 별도 구조이기 때문이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">9. 그래서 \u003ccode>had better go\u003c/code>도 같은 종류\u003c/h2>\n\u003cp>예전에 헷갈렸던 표현과 연결된다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>had better + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>~하는 게 좋겠다\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ You had better \u003cstrong>go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ You had better \u003cstrong>to go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>had better\u003c/code> 뒤에는 \u003ccode>to\u003c/code>가 없다.\u003c/p>\n\u003cp>이 표현은 문법적으로 \u003cstrong>하나의 조동사적 표현\u003c/strong>처럼 움직인다고 보면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">10. \u003ccode>to\u003c/code>가 항상 to부정사는 아니다\u003c/h2>\n\u003cp>이것도 미리 구분해 두자.\u003c/p>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">to부정사\u003c/h3>\n\u003cblockquote>\n\u003cp>I want \u003cstrong>to go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>to + 동사\u003c/code>\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">전치사 \u003ccode>to\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>I went \u003cstrong>to school\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>to + 명사\u003c/code>\u003c/p>\n\u003cp>여기서 \u003ccode>to\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>~로 / ~에\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 전치사다.\u003c/p>\n\u003cp>따라서 겉모양은 같아도 역할이 다르다.\u003c/p>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">비교\u003c/h3>\n\u003cblockquote>\n\u003cp>go \u003cstrong>to school\u003c/strong>\u003cbr>\u003ccode>to + 명사\u003c/code>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>want \u003cstrong>to study\u003c/strong>\u003cbr>\u003ccode>to + 동사\u003c/code>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">핵심\u003c/h2>\n\u003cp>to부정사의 기본 형태:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>가장 먼저 익힐 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>want to go\u003cbr>need to work\u003cbr>plan to travel\u003cbr>hope to see\u003cbr>decide to leave\u003cbr>try to finish\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>to 뒤에는 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I want \u003cstrong>go / to go\u003c/strong> home.\u003c/li>\n\u003cli>She wants to \u003cstrong>eat / eats\u003c/strong>.\u003c/li>\n\u003cli>We need \u003cstrong>to leave / leave to\u003c/strong> now.\u003c/li>\n\u003cli>He decided \u003cstrong>not to go / to not went\u003c/strong>.\u003c/li>\n\u003cli>You should \u003cstrong>go / to go\u003c/strong> home.\u003c/li>\n\u003cli>You had better \u003cstrong>go / to go\u003c/strong> now.\u003c/li>\n\u003cli>I went \u003cstrong>to school / to study\u003c/strong>.\u003cbr>→ “나는 학교에 갔다.”\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>40단계 — to부정사의 목적 표현: \u003ccode>I went there to eat\u003c/code> = “먹으러 갔다”\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 왜 to + 동사를 쓰나?","depth":2},{"id":"reading-2","label":"2. 기본 구조","depth":2},{"id":"reading-3","label":"3. want to — ~하고 싶다","depth":2},{"id":"reading-4","label":"예","depth":3},{"id":"reading-5","label":"문장 구조","depth":2},{"id":"reading-6","label":"4. need to — ~할 필요가 있다 / ~해야 한다","depth":2},{"id":"reading-7","label":"5. 자주 쓰이는 동사 + to부정사","depth":2},{"id":"reading-8","label":"6. 부정형","depth":2},{"id":"reading-9","label":"I don't want to go.","depth":3},{"id":"reading-10","label":"I decided not to go.","depth":3},{"id":"reading-11","label":"7. to 뒤에는 무조건 동사원형","depth":2},{"id":"reading-12","label":"8. 그런데 모든 동사 뒤에 to를 쓰는 것은 아니다","depth":2},{"id":"reading-13","label":"9. 그래서 had better go도 같은 종류","depth":2},{"id":"reading-14","label":"10. to가 항상 to부정사는 아니다","depth":2},{"id":"reading-15","label":"to부정사","depth":3},{"id":"reading-16","label":"전치사 to","depth":3},{"id":"reading-17","label":"비교","depth":3},{"id":"reading-18","label":"핵심","depth":2},{"id":"reading-19","label":"연습","depth":2}],"origin":"conversation","characters":3367,"aliases":{"structure":"reading-2","examples":"reading-4","contrast":"reading-17","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-5","topic-5":"reading-6","topic-6":"reading-7","topic-7":"reading-8","topic-8":"reading-11","topic-9":"reading-12","topic-10":"reading-13","topic-11":"reading-14","topic-12":"reading-18"}},{"id":40,"title":"40단계 — to부정사의 목적 표현","html":"\u003ch1 id=\"lesson-title\" data-id=\"40\">40단계 — to부정사의 목적 표현\u003c/h1>\n\u003cp>이번에는 \u003ccode>to + 동사원형\u003c/code>이 \u003cstrong>“~하기 위해 / ~하러”\u003c/strong>라는 목적을 나타내는 경우다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + 동사 + ... + to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I went to the store \u003cstrong>to buy milk\u003c/strong>.\u003cbr>나는 우유를 사러 가게에 갔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서:\u003c/p>\n\u003cblockquote>\n\u003cp>to buy = 사기 위해 / 사러\u003c/p>\n\u003c/blockquote>\n\u003cp>즉, \u003cstrong>왜 갔는지 목적\u003c/strong>을 설명한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 가장 기본적인 의미\u003c/h2>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">I went there to eat.\u003c/h3>\n\u003cblockquote>\n\u003cp>나는 먹으러 거기에 갔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cul>\n\u003cli>I = 주어\u003c/li>\n\u003cli>went = 동사\u003c/li>\n\u003cli>there = 장소\u003c/li>\n\u003cli>to eat = 목적\u003c/li>\n\u003c/ul>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>무엇을 했다 + 왜 했는가\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 연결한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">3. 이동동사와 아주 자주 쓴다\u003c/h2>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">go\u003c/h3>\n\u003cblockquote>\n\u003cp>I went out \u003cstrong>to buy coffee\u003c/strong>.\u003cbr>나는 커피를 사러 나갔다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">come\u003c/h3>\n\u003cblockquote>\n\u003cp>She came here \u003cstrong>to see me\u003c/strong>.\u003cbr>그녀는 나를 보러 여기 왔다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">travel\u003c/h3>\n\u003cblockquote>\n\u003cp>We traveled to Japan \u003cstrong>to visit our friends\u003c/strong>.\u003cbr>우리는 친구들을 만나러 일본에 갔다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">4. 이동동사가 아니어도 가능하다\u003c/h2>\n\u003cblockquote>\n\u003cp>I called her \u003cstrong>to ask a question\u003c/strong>.\u003cbr>나는 질문하려고 그녀에게 전화했다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He studied hard \u003cstrong>to pass the test\u003c/strong>.\u003cbr>그는 시험에 합격하기 위해 열심히 공부했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>to부정사 = 앞의 행동을 한 목적\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">5. \u003ccode>for\u003c/code>와 헷갈리지 않기\u003c/h2>\n\u003cp>목적을 말할 때 한국어의 “~을 위해” 때문에 \u003ccode>for\u003c/code>를 쓰고 싶어질 수 있다.\u003c/p>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">동작 목적\u003c/h3>\n\u003cblockquote>\n\u003cp>✅ I went there \u003cstrong>to eat\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ I went there \u003cstrong>for eat\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>eat\u003c/code>은 동사이므로:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>을 쓴다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">명사를 위한 것\u003c/h3>\n\u003cblockquote>\n\u003cp>I bought this \u003cstrong>for my daughter\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>나는 이것을 딸을 위해 샀다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>my daughter\u003c/code>는 명사이므로 \u003ccode>for\u003c/code>.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">비교\u003c/h2>\n\u003cblockquote>\n\u003cp>I bought this \u003cstrong>to use at work\u003c/strong>.\u003cbr>직장에서 사용하려고 이것을 샀다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I bought this \u003cstrong>for my office\u003c/strong>.\u003cbr>사무실을 위해 이것을 샀다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">6. \u003ccode>in order to\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>to + 동사원형\u003c/code>의 목적 의미를 더 분명하게 만들고 싶을 때:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>in order to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>을 쓸 수 있다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I exercise \u003cstrong>in order to stay healthy\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>건강을 유지하기 위해 운동한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 일상 영어에서는 그냥:\u003c/p>\n\u003cblockquote>\n\u003cp>I exercise \u003cstrong>to stay healthy\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>가 더 간단하고 자연스럽다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">7. \u003ccode>in order to\u003c/code>는 하나의 관용적 구조\u003c/h2>\n\u003cp>이 표현은 통째로 익히면 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>in order to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~하기 위해서\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I left early \u003cstrong>in order to avoid traffic\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>교통체증을 피하기 위해 일찍 출발했다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">8. 부정 목적\u003c/h2>\n\u003cp>“~하지 않기 위해”는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>in order not to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I left early \u003cstrong>in order not to be late\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>늦지 않기 위해 일찍 출발했다.\u003c/p>\n\u003c/blockquote>\n\u003cp>더 간단히:\u003c/p>\n\u003cblockquote>\n\u003cp>I left early \u003cstrong>not to be late\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>도 가능하지만, 목적을 분명하게 할 때는 \u003ccode>in order not to\u003c/code>가 더 명확하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">9. \u003ccode>so that\u003c/code>과의 차이\u003c/h2>\n\u003cp>목적을 나타낼 때:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>so that + 주어 + 동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>도 쓸 수 있다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I speak slowly \u003cstrong>so that you can understand me\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>네가 내 말을 이해할 수 있도록 천천히 말한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>비교:\u003c/p>\n\u003cblockquote>\n\u003cp>I speak slowly \u003cstrong>to help you understand\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 목적을 나타내지만 구조가 다르다.\u003c/p>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">to부정사\u003c/h3>\n\u003cblockquote>\n\u003cp>to + 동사원형\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">so that\u003c/h3>\n\u003cblockquote>\n\u003cp>so that + 주어 + 동사\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>so that\u003c/code>은 나중에 접속사 단계에서 자세히 다룬다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">10. 두 종류의 \u003ccode>to부정사\u003c/code> 구분\u003c/h2>\n\u003cp>앞 단계에서:\u003c/p>\n\u003cblockquote>\n\u003cp>I want \u003cstrong>to eat\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 \u003ccode>want\u003c/code>의 내용을 채워준다.\u003c/p>\n\u003cblockquote>\n\u003cp>무엇을 원해? → 먹기를\u003c/p>\n\u003c/blockquote>\n\u003cp>이번 단계에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>I went outside \u003cstrong>to eat\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는:\u003c/p>\n\u003cblockquote>\n\u003cp>왜 밖에 갔어? → 먹으려고\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 같은 \u003ccode>to eat\u003c/code>이라도 역할이 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">핵심\u003c/h2>\n\u003cp>목적을 나타낼 때:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>to + 동사원형 = ~하기 위해 / ~하러\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I went out \u003cstrong>to buy coffee\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She called me \u003cstrong>to ask a question\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I study English \u003cstrong>to communicate better\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>in order to + 동사원형 = ~하기 위해서\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-21\" data-reading-anchor=\"reading-21\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I went to the store \u003cstrong>to buy / for buy\u003c/strong> milk.\u003c/li>\n\u003cli>She came here \u003cstrong>to see / seeing\u003c/strong> me.\u003c/li>\n\u003cli>I study English \u003cstrong>to speak / for speak\u003c/strong> better.\u003c/li>\n\u003cli>I bought this \u003cstrong>for my daughter / to my daughter\u003c/strong>.\u003c/li>\n\u003cli>He left early \u003cstrong>to avoid / avoiding\u003c/strong> traffic.\u003c/li>\n\u003cli>\u003ccode>in order to\u003c/code> 뒤에는 \u003cstrong>동사원형 / 동명사\u003c/strong>가 온다.\u003c/li>\n\u003c/ol>\n\u003cp>다음은 \u003cstrong>41단계 — 동명사 \u003ccode>동사-ing\u003c/code>를 명사처럼 쓰는 구조\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 구조","depth":2},{"id":"reading-2","label":"2. 가장 기본적인 의미","depth":2},{"id":"reading-3","label":"I went there to eat.","depth":3},{"id":"reading-4","label":"3. 이동동사와 아주 자주 쓴다","depth":2},{"id":"reading-5","label":"go","depth":3},{"id":"reading-6","label":"come","depth":3},{"id":"reading-7","label":"travel","depth":3},{"id":"reading-8","label":"4. 이동동사가 아니어도 가능하다","depth":2},{"id":"reading-9","label":"5. for와 헷갈리지 않기","depth":2},{"id":"reading-10","label":"동작 목적","depth":3},{"id":"reading-11","label":"명사를 위한 것","depth":3},{"id":"reading-12","label":"비교","depth":2},{"id":"reading-13","label":"6. in order to","depth":2},{"id":"reading-14","label":"7. in order to는 하나의 관용적 구조","depth":2},{"id":"reading-15","label":"8. 부정 목적","depth":2},{"id":"reading-16","label":"9. so that과의 차이","depth":2},{"id":"reading-17","label":"to부정사","depth":3},{"id":"reading-18","label":"so that","depth":3},{"id":"reading-19","label":"10. 두 종류의 to부정사 구분","depth":2},{"id":"reading-20","label":"핵심","depth":2},{"id":"reading-21","label":"연습","depth":2}],"origin":"conversation","characters":2993,"aliases":{"structure":"reading-1","examples":"concept","contrast":"reading-12","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-4","topic-4":"reading-8","topic-5":"reading-9","topic-6":"reading-12","topic-7":"reading-13","topic-8":"reading-14","topic-9":"reading-15","topic-10":"reading-16","topic-11":"reading-19","topic-12":"reading-20"}}]);
